-- [NW Hub Protection Layer - Virtualization Wrapper] --
-- 
do
    local function _nw_exec(...)
        -- NW Hub :: Clover RPG Full (Kyoka V2)
pcall(function()
    local hui = (gethui and gethui()) or game:GetService("CoreGui")
    for _, c in ipairs(hui:GetChildren()) do
        if c.Name:find("Vesper_Kyoka") then pcall(function() c:Destroy() end) end
    end
    local lp = game:GetService("Players").LocalPlayer
    if lp and lp:FindFirstChild("PlayerGui") then
        for _, c in ipairs(lp.PlayerGui:GetChildren()) do
            if c.Name:find("Vesper_Kyoka") then pcall(function() c:Destroy() end) end
        end
    end
    if _G.CloverRPG_Cleanup then pcall(_G.CloverRPG_Cleanup) end
end);

