local function Luma(c)
	return 0.2126 * c.R + 0.7152 * c.G + 0.0722 * c.B
end

-- Couleurs dérivées de l'accent (le texte posé sur l'accent s'inverse si l'accent est clair).
local function DeriveAccent(a)
	Theme.Accent = a
	Theme.AccentDim = a:Lerp(Color3.new(0, 0, 0), 0.45)
	Theme.Accent2 = a:Lerp(Color3.new(1, 1, 1), 0.22)
	Theme.Glass = a:Lerp(Color3.new(1, 1, 1), 0.6)
	Theme.AccentSoft = a:Lerp(Theme.Panel2 or BASE_THEME.Panel2, 0.82)
	Theme.OnAccent = Luma(a) > 0.62 and Color3.fromRGB(14, 14, 16) or Color3.new(1, 1, 1)
end

for k, v in pairs(BASE_THEME) do Theme[k] = v end
DeriveAccent(BASE_THEME.Accent)

