}
Library.Prefs = Prefs

do
	if HasFS() then
		pcall(function()
			if isfile(PREFS_FILE) then
				local data = HttpService:JSONDecode(readfile(PREFS_FILE))
				if type(data) == "table" then
					for k, v in pairs(data) do Prefs[k] = v end
				end
			end
		end)
	end
end

local saveQueued = false
function K.SavePrefs()
	if not HasFS() or saveQueued then return end
	saveQueued = true
	task.delay(0.6, function()
		saveQueued = false
		pcall(function()
			if not isfolder(PREFS_DIR) then makefolder(PREFS_DIR) end
			writefile(PREFS_FILE, HttpService:JSONEncode(Prefs))
		end)
	end)
end

