--=====================================================================
-- Polices : la famille Builder de Roblox (Sans ≈ Inter, Extended ≈ Archivo, Mono)
--=====================================================================

local FONT_FAMILIES = {
	Builder    = { Text = "rbxasset://fonts/families/BuilderSans.json", Display = "rbxasset://fonts/families/BuilderExtended.json" },
	Montserrat = { Text = "rbxasset://fonts/families/Montserrat.json", Display = "rbxasset://fonts/families/Montserrat.json" },
	Nunito     = { Text = "rbxasset://fonts/families/Nunito.json", Display = "rbxasset://fonts/families/Nunito.json" },
	Roboto     = { Text = "rbxasset://fonts/families/Roboto.json", Display = "rbxasset://fonts/families/RobotoCondensed.json" },
}
Library.FontFamilies = FONT_FAMILIES
local MONO_FAMILY = "rbxasset://fonts/families/BuilderMono.json"

local function Family(role)
	if role == "Mono" then return MONO_FAMILY end
	local fam = FONT_FAMILIES[Prefs.Font] or FONT_FAMILIES.Builder
	return role == "Display" and fam.Display or fam.Text
end

local function TS(size)
	return math.max(8, math.floor((size or 13) * M.FontMul + 0.5))
end

local function FontOf(role, weight)
	return Font.new(Family(role), weight or Enum.FontWeight.Medium, Enum.FontStyle.Normal)
end
K.FontOf = FontOf
K.TS = TS

--=====================================================================
-- Utilitaires
--=====================================================================

local Registry = setmetatable({}, { __mode = "k" })   -- inst -> { prop = themeKey }
local Corners  = setmetatable({}, { __mode = "k" })   -- UICorner -> rayon de base
local Fonts    = setmetatable({}, { __mode = "k" })   -- texte -> { role, weight }
K.Registry, K.Corners, K.Fonts = Registry, Corners, Fonts

local function New(class, props, children)
	local inst = Instance.new(class)
	local parent
	if type(props) == "table" then
		parent = props.Parent
		for k, v in pairs(props) do
			if k ~= "Parent" then inst[k] = v end
		end
	end
	if children then
		for _, c in ipairs(children) do c.Parent = inst end
	end
	if parent then inst.Parent = parent end
	return inst
end

function Library:Register(inst, map)
	if type(map) ~= "table" then return inst end
	local cur = Registry[inst]
	if cur then
		for p, k in pairs(map) do cur[p] = k end
	else
		Registry[inst] = map
	end
	for prop, key in pairs(map) do
		if Theme[key] ~= nil then inst[prop] = Theme[key] end
	end
	return inst
end

local function Unregister(inst, prop)
	local map = Registry[inst]
	if map then map[prop] = nil end
end
K.Unregister = Unregister

local function Repaint()
	for inst, map in pairs(Registry) do
		if typeof(inst) == "Instance" and inst.Parent ~= nil then
			for prop, key in pairs(map) do
				local v = Theme[key]
				if v ~= nil then pcall(function() inst[prop] = v end) end
			end
		end
	end
	for _, fn in ipairs(K.ThemeHooks or {}) do pcall(fn) end
end
K.Repaint = Repaint
K.ThemeHooks = {}

function Library:SetTheme(key, color)
	if key == "Accent" then if getgenv then getgenv().Kyoka = Library; getgenv().KyokaLib = Library end
return Library:SetAccent(color) end
	Theme[key] = color
	Repaint()
end

function Library:SetAccent(color, persist)
	if typeof(color) ~= "Color3" then return end
	DeriveAccent(color)
	Repaint()
	if persist then
		Prefs.Accent = { color.R, color.G, color.B }
		K.SavePrefs()
	end
end

function Library:Connect(signal, fn)
	local conn = signal:Connect(fn)
	table.insert(Library.Connections, conn)
	return conn
end

local function Tween(inst, dur, props, style, dir, delay)
	local d = (dur or 0.18) * (Library.Motion or 1)
	local info = TweenInfo.new(d, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out, 0, false, delay or 0)
	local t = TweenService:Create(inst, info, props)
	t:Play()
	return t
end

-- Transition vers une couleur du thème, retenue pour qu'un changement de thème
-- repeigne l'objet dans son état courant (et non dans sa couleur de départ).
local function Paint(inst, dur, prop, key, style)
	local map = Registry[inst]
	if map then map[prop] = key else Registry[inst] = { [prop] = key } end
	local c = Theme[key]
	if c then Tween(inst, dur, { [prop] = c }, style) end
end
K.Paint = Paint

local function Corner(parent, radius)
	local full = radius == "full"
	local c = New("UICorner", {
		CornerRadius = full and UDim.new(1, 0) or UDim.new(0, math.floor((radius or 6) * (Prefs.Radius or 1) + 0.5)),
		Parent = parent,
	})
	if not full then Corners[c] = radius or 6 end
	return c
end

function K.SetRadiusScale(k)
	Prefs.Radius = k
	for c, base in pairs(Corners) do
		if c.Parent then c.CornerRadius = UDim.new(0, math.floor(base * k + 0.5)) end
	end
end

local function Stroke(parent, key, thickness, transparency)
	local s = New("UIStroke", {
		Thickness = thickness or 1,
		Transparency = transparency or 0,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		LineJoinMode = Enum.LineJoinMode.Round,
		Parent = parent,
	})
	Library:Register(s, { Color = key or "BorderSoft" })
	return s
end

local function Pad(parent, t, b, l, r)
	return New("UIPadding", {
		PaddingTop = UDim.new(0, t or 0), PaddingBottom = UDim.new(0, b or t or 0),
		PaddingLeft = UDim.new(0, l or 0), PaddingRight = UDim.new(0, r or l or 0),
		Parent = parent,
	})
end

local function List(parent, pad, dir, halign, valign)
	return New("UIListLayout", {
		Padding = UDim.new(0, pad or 0),
		FillDirection = dir or Enum.FillDirection.Vertical,
		SortOrder = Enum.SortOrder.LayoutOrder,
		HorizontalAlignment = halign or Enum.HorizontalAlignment.Left,
		VerticalAlignment = valign or Enum.VerticalAlignment.Top,
		Parent = parent,
	})
end

local function Seq(colors)
	local kps = {}
	for i, c in ipairs(colors) do
		table.insert(kps, ColorSequenceKeypoint.new((i - 1) / math.max(#colors - 1, 1), c))
	end
	return ColorSequence.new(kps)
end

local function NSeq(points)
	local kps = {}
	for _, p in ipairs(points) do table.insert(kps, NumberSequenceKeypoint.new(p[1], p[2])) end
	return NumberSequence.new(kps)
end
K.Seq, K.NSeq = Seq, NSeq

local function SetFontRole(lbl, role, weight)
	Fonts[lbl] = { role, weight }
	lbl.FontFace = FontOf(role, weight)
end
K.SetFontRole = SetFontRole

function K.SetFamily(name)
	if not FONT_FAMILIES[name] then return end
	Prefs.Font = name
	for lbl, info in pairs(Fonts) do
		if lbl.Parent then pcall(function() lbl.FontFace = FontOf(info[1], info[2]) end) end
	end
end

local function Label(parent, text, size, colorKey, weight, role)
	local lbl = New("TextLabel", {
		BackgroundTransparency = 1,
		Text = tostring(text or ""),
		TextSize = TS(size or 13),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		RichText = true,
		Size = UDim2.fromScale(1, 1),
		Parent = parent,
	})
	SetFontRole(lbl, role or "Text", weight or Enum.FontWeight.Medium)
	Library:Register(lbl, { TextColor3 = colorKey or "Text" })
	return lbl
end

local function Mono(parent, text, size, colorKey, weight)
	return Label(parent, text, size or 11, colorKey or "TextFaint", weight or Enum.FontWeight.Medium, "Mono")
end

local function Hit(parent, name, z)
	return New("TextButton", {
		Name = name or "Hit",
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		Selectable = false,
		Size = UDim2.fromScale(1, 1),
		ZIndex = z or 5,
		Parent = parent,
	})
end

local function MousePos()
	local m = UserInputService:GetMouseLocation()
	local inset = GuiService:GetGuiInset()
	return Vector2.new(m.X - inset.X, m.Y - inset.Y)
end

local function Round(n, decimals)
	local mult = 10 ^ (decimals or 0)
	return math.floor(n * mult + 0.5) / mult
end

local function IsClick(input)
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

local function IsMove(input)
	return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
end

K.New, K.Tween, K.Corner, K.Stroke, K.Pad, K.List = New, Tween, Corner, Stroke, Pad, List
K.Label, K.Mono, K.Hit, K.MousePos, K.Round, K.IsClick, K.IsMove = Label, Mono, Hit, MousePos, Round, IsClick, IsMove

-- Mesure d'un texte (en unités logiques).
function K.TextWidth(text, size, role, weight)
	local ok, res = pcall(function()
		local p = Instance.new("GetTextBoundsParams")
		p.Text = tostring(text)
		p.Font = FontOf(role or "Text", weight or Enum.FontWeight.Medium)
		p.Size = TS(size or 13)
		p.Width = 10000
		return TextService:GetTextBoundsAsync(p)
	end)
	if ok and res then return res.X end
	return #tostring(text) * TS(size or 13) * 0.55
end

