--=====================================================================
-- ScreenGui racine et calques
--=====================================================================

local function GetParent()
	local lp = game:GetService("Players").LocalPlayer
	if lp and lp:FindFirstChild("PlayerGui") then return lp.PlayerGui end
	local ok, hui = pcall(function() return gethui and gethui() end)
	if ok and hui then return hui end
	local ok2, cg = pcall(function() return game:GetService("CoreGui") end)
	if ok2 and cg then
		local writable = pcall(function()
			local probe = Instance.new("Folder")
			probe.Parent = cg
			probe:Destroy()
		end)
		if writable then return cg end
	end
	return LocalPlayer:WaitForChild("PlayerGui")
end

-- « Vesper_Kyoka_ » : les scripts existants nettoient une ancienne instance par ce nom.
local ScreenGui = New("ScreenGui", {
	Name = "Vesper_Kyoka_" .. tostring(math.random(1e5, 1e6)),
	ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
	ResetOnSpawn = false,
	IgnoreGuiInset = true,
	DisplayOrder = 999,
})
pcall(function() if syn and syn.protect_gui then syn.protect_gui(ScreenGui) end end)
ScreenGui.Parent = GetParent()
Library.ScreenGui = ScreenGui

ScreenGuiSize = function() return ScreenGui.AbsoluteSize end

local function ViewportSize()
	local vp = ScreenGui.AbsoluteSize
	if vp.X <= 1 or vp.Y <= 1 then
		local cam = workspace.CurrentCamera
		vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
	end
	return vp
end
K.ViewportSize = ViewportSize

-- Échelle en unités Vesper : 2 = taille nominale en 1080p ; facteur réel = Scale / 2.
local ScaleTargets = setmetatable({}, { __mode = "k" })

local function AutoScale()
	if Library.Mobile then return 2 end
	local h = ViewportSize().Y
	local f = math.clamp(h / 1040, 0.8, 2)
	return Round(f * 2, 2)
end
K.AutoScale = AutoScale

Library.Scale = tonumber(Prefs.Scale) or AutoScale()

local function Factor() return (Library.Scale or 2) / 2 end
K.Factor = Factor

local function Scalable(parent)
	local s = New("UIScale", { Scale = Factor(), Parent = parent })
	ScaleTargets[s] = true
	return s
end
K.Scalable = Scalable

function Library:SetScale(n)
	n = tonumber(n)
	if not n then return end
	Library.Scale = math.clamp(n, 0.8, 4)
	for s in pairs(ScaleTargets) do
		if s.Parent then s.Scale = Factor() end
	end
	if Library.Window and Library.Window.ApplyScale then Library.Window:ApplyScale(Library.Scale) end
end

local function Layer(name, z)
	return New("Frame", { Name = name, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = z, Parent = ScreenGui })
end
local PopupLayer = Layer("PopupLayer", 500)
local FxLayer = Layer("FxLayer", 860)
Library.PopupLayer, K.PopupLayer, K.FxLayer = PopupLayer, PopupLayer, FxLayer

-- Position souris dans le repère d'un calque plein écran.
local function MouseLocal()
	local o = PopupLayer.AbsolutePosition
	local p = MousePos()
	return p.X - o.X, p.Y - o.Y
end
K.MouseLocal = MouseLocal

local function InputPos(input)
	if input and input.UserInputType == Enum.UserInputType.Touch then
		return Vector2.new(input.Position.X, input.Position.Y)
	end
	return MousePos()
end
K.InputPos = InputPos

local ModalCatcher = New("TextButton", {
	Name = "Modal", Text = "", BackgroundTransparency = 1,
	Size = UDim2.fromOffset(1, 1), Position = UDim2.fromOffset(-4, -4),
	Modal = true, Parent = ScreenGui,
})
K.Modal = ModalCatcher

local ActivePopup
function K.CloseActivePopup()
	if ActivePopup then
		local f = ActivePopup
		ActivePopup = nil
		pcall(f)
	end
end
function K.SetActivePopup(fn) ActivePopup = fn end
function K.GetActivePopup() return ActivePopup end

function K.PointInside(gui, p)
	local a, s = gui.AbsolutePosition, gui.AbsoluteSize
	return p.X >= a.X and p.X <= a.X + s.X and p.Y >= a.Y and p.Y <= a.Y + s.Y
end

--=====================================================================
-- Médias distants (vidéo d'intro, voix) : cache disque + getcustomasset
--=====================================================================

local customAsset = getcustomasset or getsynasset
K.MediaReady = {}

-- Renvoie un chemin jouable ou nil. Bloquant au premier téléchargement : appeler dans un task.
function K.Media(name, minBytes)
	if K.MediaReady[name] then return K.MediaReady[name] end
	local env = (getgenv and getgenv()) or _G
	-- Tests : { ["intro.webm"] = "rbxasset://…" } fourni par le script de démo.
	local localMedia = (env and env.KYOKA_LOCAL_MEDIA) or Library.LocalMedia
	if type(localMedia) == "table" then
		K.MediaReady[name] = localMedia[name]
		return localMedia[name]
	end
	if not (customAsset and HasFS()) then return nil end
	local path = PREFS_DIR .. "/media/" .. name
	local ok, asset = pcall(function()
		if not isfolder(PREFS_DIR) then makefolder(PREFS_DIR) end
		if not isfolder(PREFS_DIR .. "/media") then makefolder(PREFS_DIR .. "/media") end
		if not isfile(path) then
			local body = game:HttpGet(Library.MediaBase .. name)
			if type(body) ~= "string" or #body < (minBytes or 2000) or body:sub(1, 15):lower():find("<!doctype") then
				error("bad media")
			end
			writefile(path, body)
		end
		return customAsset(path)
	end)
	if ok and asset then
		K.MediaReady[name] = asset
		return asset
	end
	return nil
end

