	Splash   = { Id = Rbx(74227218855270), Volume = 1, Speed = 1, Voice = false, Group = "Intro" },
}
Library.SoundFailed = nil

local SoundPool = {}

function Library:PlaySound(name, opts)
	local cfg = Library.Sound[name]
	if not cfg or not cfg.Id or not Library.Sound.Enabled or Prefs.Sound == false then return end
	if cfg.Group == "UI" and Prefs.UISounds == false then return end
	opts = opts or {}
	local pool = SoundPool[name]
	if not pool then
		pool = { i = 0 }
		for j = 1, (cfg.Group == "UI" and 3 or 1) do
			pool[j] = New("Sound", { Name = "Kyoka_" .. name, Parent = SoundService })
		end
		SoundPool[name] = pool
	end
	pool.i = pool.i % #pool + 1
	local snd = pool[pool.i]
	if not snd.Parent then snd.Parent = SoundService end
	local id = cfg.Id
	if type(id) == "table" then id = id[math.random(1, #id)] end
	if snd.SoundId ~= id then snd.SoundId = id end
	snd.Volume = (opts.Volume or cfg.Volume or 1) * (Library.Sound.Volume or 1) * (tonumber(Prefs.Volume) or 0.6) / 0.6
	snd.PlaybackSpeed = (opts.Speed or cfg.Speed or 1) * (opts.Pitch or 1)
	snd.TimePosition = opts.Start or 0
	pcall(function() snd:Play() end)
	return snd
end

function Library:SetSoundEnabled(v)
	Library.Sound.Enabled = v and true or false
end

