--=====================================================================
-- Effets visuels
-- Sobres dans le menu (ondes, halos), spectaculaires aux transitions
-- (miroir qui se reforme / vole en éclats, fissures, flash).
--=====================================================================

local FX = {}
Library.FX = FX
K.FX = FX

local function FxOn() if getgenv then getgenv().Kyoka = Library; getgenv().KyokaLib = Library end
return Library.Effects ~= false or Prefs.OpenFxUser == true end
local function Particles() return FxOn() and Prefs.Particles ~= false end

-- Onde blanche depuis le point cliqué (dans un bouton qui coupe ses enfants).
function FX.Ripple(gui, point, color)
	if not FxOn() then return end
	local f = math.max(Factor(), 0.01)
	local pos = gui.AbsolutePosition
	local lx, ly = (point.X - pos.X) / f, (point.Y - pos.Y) / f
	local ring = FxImage(gui, "glow", (gui.ZIndex or 1) + 2)
	ring.AnchorPoint = Vector2.new(0.5, 0.5)
	ring.Position = UDim2.fromOffset(lx, ly)
	ring.Size = UDim2.fromOffset(8, 8)
	ring.ImageColor3 = color or Color3.new(1, 1, 1)
	ring.ImageTransparency = 0.82
	local d = math.max(gui.AbsoluteSize.X, gui.AbsoluteSize.Y) / f * 2.4
	Tween(ring, 0.6, { Size = UDim2.fromOffset(d, d), ImageTransparency = 1 }, Enum.EasingStyle.Quart)
	task.delay(0.62 * Library.Motion, function() ring:Destroy() end)
end

-- Halo d'accent qui s'allume puis s'éteint derrière un contrôle (interrupteur, etc.).
function FX.Pulse(gui, color, scale)
	if not FxOn() then return end
	local g = FxImage(gui, "glow", math.max((gui.ZIndex or 2) - 1, 1))
	g.AnchorPoint = Vector2.new(0.5, 0.5)
	g.Position = UDim2.fromScale(0.5, 0.5)
	g.Size = UDim2.fromScale(1.4, 2.2)
	g.ImageColor3 = color or Theme.Accent
	g.ImageTransparency = 0.55
	Tween(g, 0.55, { Size = UDim2.fromScale((scale or 2.6), (scale or 2.6) * 1.6), ImageTransparency = 1 }, Enum.EasingStyle.Quart)
	task.delay(0.6 * Library.Motion, function() g:Destroy() end)
end

-- Poussière de lumière qui jaillit d'un point écran.
function FX.Burst(point, count, color)
	if not Particles() then return end
	local o = FxLayer.AbsolutePosition
	local cx, cy = point.X - o.X, point.Y - o.Y
	for _ = 1, count or 8 do
		local sz = math.random(5, 10)
		local p = FxImage(FxLayer, "glow", 870)
		p.AnchorPoint = Vector2.new(0.5, 0.5)
		p.Position = UDim2.fromOffset(cx, cy)
		p.Size = UDim2.fromOffset(sz, sz)
		p.ImageColor3 = color or Theme.Glass
		p.ImageTransparency = 0.1
		local a = math.random() * math.pi * 2
		local d = 14 + math.random() * 26
		Tween(p, 0.55, {
			Position = UDim2.fromOffset(cx + math.cos(a) * d, cy + math.sin(a) * d - 6),
			ImageTransparency = 1,
			Size = UDim2.fromOffset(2, 2),
		}, Enum.EasingStyle.Quart)
		task.delay(0.6 * Library.Motion, function() p:Destroy() end)
	end
end

-- Filet lumineux qui balaie un cadre (apparition d'une carte, d'un groupe).
function FX.Sweep(gui, delay, duration, transparency)
	if not FxOn() then return end
	local s = FxImage(gui, "streak", (gui.ZIndex or 1) + 4)
	s.AnchorPoint = Vector2.new(0.5, 0.5)
	s.Rotation = 90
	s.Size = UDim2.new(0, 260, 0, 60)
	s.Position = UDim2.new(0, -40, 0.5, 0)
	s.ImageTransparency = transparency or 0.86
	task.delay(delay or 0, function()
		if s.Parent then
			Tween(s, duration or 0.8, { Position = UDim2.new(1, 40, 0.5, 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut)
		end
	end)
	task.delay(((delay or 0) + (duration or 0.8)) * Library.Motion + 0.1, function() s:Destroy() end)
end

-- Flash blanc plein écran (ou dans un rectangle du calque d'effets).
function FX.Flash(strength, duration, rect)
	if not FxOn() then return end
	local f = New("Frame", {
		BackgroundColor3 = Color3.new(1, 1, 1),
		BackgroundTransparency = 1 - (strength or 0.35),
		BorderSizePixel = 0,
		Size = rect and UDim2.fromOffset(rect.w, rect.h) or UDim2.fromScale(1, 1),
		Position = rect and UDim2.fromOffset(rect.x, rect.y) or UDim2.new(),
		ZIndex = 880,
		Parent = FxLayer,
	})
	if rect then Corner(f, 12) end
	Tween(f, duration or 0.45, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad)
	task.delay((duration or 0.45) * Library.Motion + 0.05, function() f:Destroy() end)
end

-- Onde de choc : anneau qui s'élargit depuis un point écran.
function FX.Shockwave(point, size, color)
	if not FxOn() then return end
	local o = FxLayer.AbsolutePosition
	local r = FxImage(FxLayer, "ring", 875)
	r.AnchorPoint = Vector2.new(0.5, 0.5)
	r.Position = UDim2.fromOffset(point.X - o.X, point.Y - o.Y)
	r.Size = UDim2.fromOffset(10, 10)
	r.ImageColor3 = color or Color3.new(1, 1, 1)
	r.ImageTransparency = 0.1
	Tween(r, 0.7, { Size = UDim2.fromOffset(size or 420, size or 420), ImageTransparency = 1 }, Enum.EasingStyle.Quart)
	task.delay(0.72 * Library.Motion, function() r:Destroy() end)
end

-- Secousse d'un objet positionné en Offset.
function FX.Shake(gui, amount, duration)
	if not FxOn() then return end
	local base = gui.Position
	local t0 = os.clock()
	local conn
	conn = RunService.RenderStepped:Connect(function()
		local t = os.clock() - t0
		if t > (duration or 0.25) or not gui.Parent then
			conn:Disconnect()
			gui.Position = base
			return
		end
		local k = (1 - t / (duration or 0.25)) * (amount or 5)
		gui.Position = base + UDim2.fromOffset(math.random(-100, 100) / 100 * k, math.random(-100, 100) / 100 * k)
	end)
end

--=====================================================================
-- Miroir : fissures, éclats qui se reforment ou volent en éclats
--=====================================================================

local MW, MH = 720, 450
local IMPACT = Vector2.new(360, 207)

-- Fissures posées sur un rectangle (repère du calque d'effets), avec flash.
function FX.Cracks(rect, z)
	if not FxOn() then return function() end end
	local c = New("ImageLabel", {
		Name = "Cracks",
		BackgroundTransparency = 1,
		Image = Assets.Cracks,
		ImageTransparency = 1,
		ImageColor3 = Theme.Glass,
		Position = UDim2.fromOffset(rect.x, rect.y),
		Size = UDim2.fromOffset(rect.w, rect.h),
		ScaleType = Enum.ScaleType.Stretch,
		ZIndex = z or 866,
		Parent = FxLayer,
	})
	Tween(c, 0.07, { ImageTransparency = 0.05 }, Enum.EasingStyle.Linear)
	FX.Flash(0.18, 0.35, rect)
	return function()
		Tween(c, 0.2, { ImageTransparency = 1 })
		task.delay(0.22, function() c:Destroy() end)
	end, c
end

local function MakeShards(rect, z)
	local sx, sy = rect.w / MW, rect.h / MH
	local list = {}
	for _, s in ipairs(K.ShardList) do
		local ring, x, y, w, h, ax, ay = s[1], s[2], s[3], s[4], s[5], s[6], s[7]
		local cx, cy = rect.x + (x + w / 2) * sx, rect.y + (y + h / 2) * sy
		local im = New("ImageLabel", {
			Name = "Shard",
			BackgroundTransparency = 1,
			Image = Assets.Shards,
			ImageRectOffset = Vector2.new(ax, ay),
			ImageRectSize = Vector2.new(w, h),
			ImageColor3 = Theme.Glass:Lerp(Color3.new(1, 1, 1), 0.4),
			ImageTransparency = 1,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromOffset(cx, cy),
			Size = UDim2.fromOffset(w * sx + 1, h * sy + 1),
			ZIndex = z or 865,
			Parent = FxLayer,
		})
		table.insert(list, {
			Img = im, Ring = ring, X = cx, Y = cy,
			DX = (x + w / 2 - IMPACT.X) * sx, DY = (y + h / 2 - IMPACT.Y) * sy,
		})
	end
	return list
end

local function Dissolve(list)
	for _, sh in ipairs(list) do
		if sh.Img.Parent then Tween(sh.Img, 0.14, { ImageTransparency = 1 }) end
	end
	task.delay(0.16, function()
		for _, sh in ipairs(list) do sh.Img:Destroy() end
	end)
end

-- Les éclats convergent et reforment le miroir ; onFlash révèle la fenêtre.
function FX.Assemble(rect, onFlash, onDone)
	local list = MakeShards(rect)
	for _, sh in ipairs(list) do
		local len = math.max(math.sqrt(sh.DX ^ 2 + sh.DY ^ 2), 1)
		local far = 260 + math.random() * 380 + sh.Ring * 40
		sh.Img.Position = UDim2.fromOffset(sh.X + sh.DX / len * far, sh.Y + sh.DY / len * far)
		sh.Img.Rotation = (math.random() - 0.5) * 300
		local info = TweenInfo.new(0.62 * Library.Motion, Enum.EasingStyle.Quint, Enum.EasingDirection.Out, 0, false,
			(4 - sh.Ring) * 0.03 * Library.Motion + math.random() * 0.08)
		TweenService:Create(sh.Img, info, {
			Position = UDim2.fromOffset(sh.X, sh.Y), Rotation = 0, ImageTransparency = 0.35,
		}):Play()
	end
	local cancelled = false
	task.delay(0.78 * Library.Motion, function()
		if cancelled then return end
		FX.Flash(0.22, 0.4, rect)
		if onFlash then onFlash() end
		for _, sh in ipairs(list) do Tween(sh.Img, 0.32, { ImageTransparency = 1 }) end
		task.delay(0.34 * Library.Motion, function()
			if cancelled then return end
			for _, sh in ipairs(list) do sh.Img:Destroy() end
			if onDone then onDone() end
		end)
	end)
	return function()
		if cancelled then return end
		cancelled = true
		Dissolve(list)
	end
end

-- Le miroir éclate : les éclats partent du point d'impact puis tombent.
-- toward = true : ils volent vers l'écran (fin de l'intro).
function FX.Shatter(rect, onDone, toward, z)
	local list = MakeShards(rect, z)
	for _, sh in ipairs(list) do
		sh.Img.ImageTransparency = 0.2
		sh.R = 0
		local len = math.max(math.sqrt(sh.DX ^ 2 + sh.DY ^ 2), 1)
		local push = (toward and 9 or 4) + math.random() * 5
		sh.VX = sh.DX / len * push + (math.random() - 0.5) * 2
		sh.VY = sh.DY / len * push * 0.7 - (toward and 0 or 2 + math.random() * 3)
		sh.VR = (math.random() - 0.5) * 10
		sh.S = 1
		sh.W, sh.H = sh.Img.Size.X.Offset, sh.Img.Size.Y.Offset
		sh.Delay = (toward and 0 or sh.Ring * 0.025)
	end
	local t = 0
	local conn
	conn = RunService.RenderStepped:Connect(function(dt)
		t += dt / math.max(Library.Motion, 0.2)
		local k = math.min(dt * 60, 3)
		local fade = math.clamp(1 - math.max(0, t - 0.45) / 0.75, 0, 1)
		for _, sh in ipairs(list) do
			if t >= sh.Delay then
				if toward then
					sh.S += 0.035 * k
					sh.VX *= 1.01
				else
					sh.VY += 0.36 * k
				end
				sh.X += sh.VX * k
				sh.Y += sh.VY * k
				sh.R += sh.VR * k
				sh.Img.Position = UDim2.fromOffset(sh.X, sh.Y)
				sh.Img.Rotation = sh.R
				if toward then sh.Img.Size = UDim2.fromOffset(sh.W * sh.S, sh.H * sh.S) end
				sh.Img.ImageTransparency = 1 - fade * 0.8
			end
		end
		if t >= 1.3 then
			conn:Disconnect()
			for _, sh in ipairs(list) do sh.Img:Destroy() end
			if onDone then onDone() end
		end
	end)
	table.insert(Library.Connections, conn)
	return function()
		if conn.Connected then
			conn:Disconnect()
			Dissolve(list)
		end
	end
end

-- Rectangle d'un objet dans le repère du calque d'effets.
function FX.RectOf(gui)
	local o = FxLayer.AbsolutePosition
	local p, s = gui.AbsolutePosition - o, gui.AbsoluteSize
	return { x = p.X, y = p.Y, w = s.X, h = s.Y }
end

