-- Repères d'aimantation (déplacement de la fenêtre)
--=====================================================================

local Guides = {}
for i = 1, 2 do
	local g = New("Frame", {
		Name = "Guide",
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		BackgroundTransparency = 1,
		ZIndex = 858,
		Parent = ScreenGui,
	})
	Library:Register(g, { BackgroundColor3 = "Accent" })
	New("UIGradient", { Rotation = i == 1 and 90 or 0, Transparency = NSeq({ { 0, 1 }, { 0.5, 0 }, { 1, 1 } }), Parent = g })
	Guides[i] = g
end

-- axis 1 = trait vertical à x, 2 = trait horizontal à y ; nil = caché.
function FX.Guide(axis, value)
	local g = Guides[axis]
	if value == nil then
		if g.BackgroundTransparency < 1 then Tween(g, 0.2, { BackgroundTransparency = 1 }) end
		return
	end
	if axis == 1 then
		g.Size = UDim2.new(0, 1, 1, 0)
		g.Position = UDim2.fromOffset(value, 0)
	else
		g.Size = UDim2.new(1, 0, 0, 1)
		g.Position = UDim2.fromOffset(0, value)
	end
	if g.BackgroundTransparency > 0.5 then Tween(g, 0.12, { BackgroundTransparency = 0.35 }) end
end

--=====================================================================
-- Éléments (mixin partagé par les groupes)
--=====================================================================

local Elements = {}
K.Elements = Elements

local function TrackRow(group, row, text)
	if group.Rows then
		table.insert(group.Rows, { Frame = row, Text = string.lower(tostring(text or "")) })
		if group.UpdateCount then group.UpdateCount() end
	end
end

-- Clic droit sur une ligne : menu contextuel (épingler, réinitialiser…), défini plus loin.
local function BindContext(hit, obj)
	Library:Connect(hit.MouseButton2Click, function()
		if K.OpenContext then K.OpenContext(obj) end
	end)
end
K.BindContext = BindContext

local function RowHover(row)
	local hover = New("Frame", {
		Name = "Hover",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 16, 1, 0),
		Position = UDim2.fromOffset(-8, 0),
		ZIndex = 1,
		Parent = row,
	})
	Library:Register(hover, { BackgroundColor3 = "ElementHover" })
	Corner(hover, 7)
	return hover
end

local function FitLabel(lbl, addons, container)
	local function fit()
		local total = container.AbsoluteSize.X
		if total <= 0 then return end
		local used = addons.AbsoluteSize.X
		local ratio = used > 0 and (used / total) or 0
		lbl.Size = UDim2.new(1 - ratio, used > 0 and -12 or 0, 1, 0)
	end
	Library:Connect(addons:GetPropertyChangedSignal("AbsoluteSize"), fit)
	Library:Connect(container:GetPropertyChangedSignal("AbsoluteSize"), fit)
	task.defer(fit)
end

local function Addons(parent)
	local right = New("Frame", {
		Name = "Addons",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		ZIndex = 10,
		Parent = parent,
	})
	List(right, 8, Enum.FillDirection.Horizontal, Enum.HorizontalAlignment.Right, Enum.VerticalAlignment.Center)
	return right
end

local function TipOn(hit, tip)
	if not tip then return end
	Library:Connect(hit.MouseEnter, function() Library:ShowTooltip(tip) end)
	Library:Connect(hit.MouseLeave, function() Library:HideTooltip() end)
end

local function CompactRow(group, text, height, tip)
	local row = New("Frame", {
		Name = "Row",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, height or M.Row),
		LayoutOrder = group.NextOrder and group:NextOrder() or 0,
		Parent = group.Container,
	})
	local hover = RowHover(row)
	local lbl = Label(row, text, 13.5, "TextDim")
	lbl.Size = UDim2.new(1, -M.AddonSpace, 1, 0)
	lbl.TextTruncate = Enum.TextTruncate.AtEnd
	lbl.ZIndex = 2
	local right = Addons(row)
	FitLabel(lbl, right, row)
	if tip then TipOn(Hit(row, "Tip", 2), tip) end
	TrackRow(group, row, text)
	return row, lbl, right, hover
end

local function WideRow(group, text, height, tip)
	local row = New("Frame", {
		Name = "Row",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, height),
		LayoutOrder = group.NextOrder and group:NextOrder() or 0,
		Parent = group.Container,
	})
	local hover = RowHover(row)
	local head = New("Frame", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(0, 5),
		Size = UDim2.new(1, 0, 0, 20),
		ZIndex = 2,
		Parent = row,
	})
	local lbl = Label(head, text, 13.5, "TextDim")
	lbl.Size = UDim2.new(1, -M.AddonSpace, 1, 0)
	lbl.TextTruncate = Enum.TextTruncate.AtEnd
	lbl.ZIndex = 2
	local right = Addons(head)
	FitLabel(lbl, right, head)
	if tip then TipOn(Hit(head, "Tip", 2), tip) end
	TrackRow(group, row, text)
	return row, lbl, right, head, hover
end

local function Bind(obj, flag, default)
	obj.Flag = flag
	obj.Value = default
	obj.Default = default
	if flag then
		Library.Flags[flag] = default
		Library.Options[flag] = obj
	end
	return obj
end
K.Bind = Bind

local MiniToggle, MiniKeybind, MiniColorPicker

local function Addonable(obj, holder)
	function obj:AddToggle(flag, opts) MiniToggle(holder, flag, opts or {}) return obj end
	function obj:AddKeybind(flag, opts) MiniKeybind(holder, flag, opts or {}) return obj end
	function obj:AddColorPicker(flag, opts) MiniColorPicker(holder, flag, opts or {}) return obj end
	return obj
end

local function HoverRow(hit, lbl, hover, onEnter, onLeave)
	Library:Connect(hit.MouseEnter, function()
		if lbl then Paint(lbl, 0.12, "TextColor3", "Text") end
		if hover then Tween(hover, 0.14, { BackgroundTransparency = 0.45 }) end
		if onEnter then onEnter() end
	end)
	Library:Connect(hit.MouseLeave, function()
		if hover then Tween(hover, 0.2, { BackgroundTransparency = 1 }) end
		if onLeave then onLeave() end
	end)
end

--=====================================================================
-- Interrupteur
--=====================================================================

local function Switch(parent, w, h)
	w, h = w or M.SwitchW, h or M.SwitchH
	local track = New("Frame", {
		Name = "Switch",
		Size = UDim2.fromOffset(w, h),
		LayoutOrder = 1000,
		ZIndex = 11,
		Parent = parent,
	})
	Library:Register(track, { BackgroundColor3 = "Track" })
	Corner(track, "full")
	local k = h - 6
	local knob = New("Frame", {
		Name = "Knob",
		Size = UDim2.fromOffset(k, k),
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 3, 0.5, 0),
		BorderSizePixel = 0,
		ZIndex = 13,
		Parent = track,
	})
	Corner(knob, "full")
	local on = false
	local function colors()
		track.BackgroundColor3 = on and Theme.Accent or Theme.Track
		knob.BackgroundColor3 = on and Theme.OnAccent or Color3.fromRGB(139, 139, 148)
	end
	table.insert(K.ThemeHooks, function() if track.Parent then colors() end end)
	Unregister(track, "BackgroundColor3")
	local function set(v, instant)
		on = v and true or false
		local d = instant and 0 or 1
		Tween(track, 0.22 * d, { BackgroundColor3 = on and Theme.Accent or Theme.Track })
		Tween(knob, 0.22 * d, { BackgroundColor3 = on and Theme.OnAccent or Color3.fromRGB(139, 139, 148) })
		-- Le bouton s'étire en glissant puis reprend sa forme.
		Tween(knob, 0.32 * d, { Position = on and UDim2.new(1, -k - 3, 0.5, 0) or UDim2.new(0, 3, 0.5, 0) }, Enum.EasingStyle.Quint)
		if not instant then
			Tween(knob, 0.12, { Size = UDim2.fromOffset(k * 1.45, k) }, Enum.EasingStyle.Quad)
			task.delay(0.12 * Library.Motion, function()
				Tween(knob, 0.22, { Size = UDim2.fromOffset(k, k) }, Enum.EasingStyle.Back)
			end)
		end
	end
	colors()
	return track, set, knob
end
K.Switch = Switch

--=====================================================================
-- Toggle
--=====================================================================

local function LockChip(parent)
	local chip = New("Frame", {
		Name = "Lock",
		Size = UDim2.fromOffset(0, 20),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 990,
		Visible = false,
		ZIndex = 11,
		Parent = parent,
	})
	Library:Register(chip, { BackgroundColor3 = "AccentSoft" })
	Corner(chip, 5)
	Pad(chip, 0, 0, 6, 7)
	List(chip, 4, Enum.FillDirection.Horizontal, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)
	local ic = Icon(chip, "lock", 11, "Glass", 12)
	ic.LayoutOrder = 1
	local t = Mono(chip, "PREMIUM", 9.5, "Glass", Enum.FontWeight.Bold)
	t.AutomaticSize = Enum.AutomaticSize.X
	t.Size = UDim2.new(0, 0, 1, 0)
	t.LayoutOrder = 2
	t.ZIndex = 12
	return chip
end

function Elements:AddToggle(flag, opts)
	opts = opts or {}
	local text = opts.Text or opts.Name or flag
	local row, lbl, addons, hover = CompactRow(self, text, M.Row)
	local track, setVisual, knob = Switch(addons)
	local lock = LockChip(addons)

	local obj = Bind({ Type = "Toggle" }, flag, opts.Default == true)
	obj.Callback = opts.Callback
	obj.Label, obj.Row, obj.Text = lbl, row, text
	obj.Locked = opts.Locked == true
	obj.Changed = {}

	local hovering = false
	local function paintLabel()
		local key = obj.Locked and "TextFaint" or ((obj.Value or hovering) and "Text" or "TextDim")
		Paint(lbl, 0.14, "TextColor3", key)
	end

	local function refresh(fire, instant)
		setVisual(obj.Value, instant)
		paintLabel()
		if flag then Library.Flags[flag] = obj.Value end
		if fire and obj.Callback then task.spawn(obj.Callback, obj.Value) end
		for _, fn in ipairs(obj.Changed) do task.spawn(fn, obj.Value) end
	end

	function obj:Set(value, silent)
		local before = obj.Value
		obj.Value = value and true or false
		refresh(not silent)
		if not silent and obj.Value ~= before then
			Library:PlaySound(obj.Value and "ToggleOn" or "ToggleOff")
			if obj.Value then
				FX.Pulse(track)
				task.defer(function() FX.Burst(knob.AbsolutePosition + knob.AbsoluteSize / 2, 6) end)
			end
		end
	end
	function obj:Get() return obj.Value end
	function obj:SetText(t) lbl.Text = t; obj.Text = t end
	function obj:SetLocked(v)
		obj.Locked = v and true or false
		lock.Visible = obj.Locked
		track.Visible = not obj.Locked
		paintLabel()
	end
	function obj:OnChanged(fn) table.insert(obj.Changed, fn) end

	local hit = Hit(row, "Toggle", 6)
	Library:Connect(hit.MouseButton1Click, function()
		if obj.Locked then
			Library:PlaySound("Error")
			FX.Shake(lock, 3, 0.2)
			Library:Notify({ Title = text, Content = opts.LockedText or "Premium only. Get a key to unlock it.", Duration = 3, Type = "warning" })
			return
		end
		obj:Set(not obj.Value)
	end)
	HoverRow(hit, nil, hover, function()
		hovering = true
		paintLabel()
		if opts.Tooltip then Library:ShowTooltip(opts.Tooltip) end
	end, function()
		hovering = false
		paintLabel()
		Library:HideTooltip()
	end)
	BindContext(hit, obj)

	obj:SetLocked(obj.Locked)
	refresh(false, true)
	if opts.Default and opts.Callback then task.spawn(opts.Callback, true) end
	return Addonable(obj, addons)
end

MiniToggle = function(holder, flag, opts)
	local track, setVisual = Switch(holder, math.floor(M.SwitchW * 0.85), math.floor(M.SwitchH * 0.85))
	track.LayoutOrder = 500
	local obj = Bind({ Type = "Toggle" }, flag, opts.Default == true)
	obj.Callback = opts.Callback
	obj.Text = opts.Text or flag
	function obj:Set(value, silent)
		obj.Value = value and true or false
		setVisual(obj.Value)
		if flag then Library.Flags[flag] = obj.Value end
		if not silent then
			Library:PlaySound(obj.Value and "ToggleOn" or "ToggleOff")
			if obj.Callback then task.spawn(obj.Callback, obj.Value) end
		end
	end
	function obj:Get() return obj.Value end
	local hit = Hit(track, "MiniToggle", 14)
	Library:Connect(hit.MouseButton1Click, function() obj:Set(not obj.Value) end)
	TipOn(hit, opts.Tooltip)
	setVisual(obj.Value, true)
	return obj
end

--=====================================================================
-- Bouton
--=====================================================================

function Elements:AddButton(text, opts)
	opts = opts or {}
	if type(text) == "table" then opts = text; text = opts.Text end
	local callback = opts.Callback or opts.Func

	local holder = New("Frame", {
		Name = "ButtonRow",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, M.Button + 6),
		LayoutOrder = self.NextOrder and self:NextOrder() or 0,
		Parent = self.Container,
	})
	TrackRow(self, holder, text)

	local btn = New("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.new(1, 0, 0, M.Button),
		ClipsDescendants = true,
		ZIndex = 2,
		Parent = holder,
	})
	Corner(btn, 7)
	local stroke = Stroke(btn, "Border")
	local press = New("UIScale", { Scale = 1, Parent = btn })

	local inner = New("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 3, Parent = btn })
	List(inner, 7, Enum.FillDirection.Horizontal, Enum.HorizontalAlignment.Center, Enum.VerticalAlignment.Center)
	local lbl = Label(inner, text or "Button", 13.5, "Text", Enum.FontWeight.SemiBold)
	lbl.AutomaticSize = Enum.AutomaticSize.X
	lbl.Size = UDim2.new(0, 0, 1, 0)
	lbl.LayoutOrder = 2
	lbl.ZIndex = 4
	if opts.Icon then
		local ic = Icon(inner, opts.Icon, 15, nil, 4)
		ic.LayoutOrder = 1
		Library:Register(ic, { ImageColor3 = opts.Accent and "OnLight" or (opts.Danger and "Danger" or "TextDim") })
	end

	local base, hoverKey, textKey
	if opts.Accent then
		base, hoverKey, textKey = "Light", "Light", "OnLight"
		stroke.Transparency = 1
	elseif opts.Danger then
		base, hoverKey, textKey = "Element", "ElementHover", "Danger"
	else
		base, hoverKey, textKey = "Element", "ElementHover", "Text"
	end
	Library:Register(btn, { BackgroundColor3 = base })
	Library:Register(lbl, { TextColor3 = textKey })

	local obj = { Type = "Button", Instance = btn, Text = text, Callback = callback, Row = holder }
	local hit = Hit(btn, "ButtonHit", 6)
	Library:Connect(hit.MouseEnter, function()
		if opts.Accent then
			Tween(btn, 0.12, { BackgroundColor3 = Color3.new(1, 1, 1) })
		else
			Paint(btn, 0.12, "BackgroundColor3", hoverKey)
			Tween(stroke, 0.12, { Color = opts.Danger and Theme.Danger:Lerp(Theme.Border, 0.4) or Theme.TextFaint })
		end
		if opts.Tooltip then Library:ShowTooltip(opts.Tooltip) end
	end)
	Library:Connect(hit.MouseLeave, function()
		Paint(btn, 0.16, "BackgroundColor3", base)
		Paint(stroke, 0.16, "Color", "Border")
		Tween(press, 0.2, { Scale = 1 })
		Library:HideTooltip()
	end)
	Library:Connect(hit.MouseButton1Down, function()
		Tween(press, 0.08, { Scale = 0.975 })
		FX.Ripple(btn, MousePos(), opts.Accent and Theme.OnLight or nil)
	end)
	Library:Connect(hit.MouseButton1Up, function()
		Tween(press, 0.25, { Scale = 1 }, Enum.EasingStyle.Back)
	end)
	Library:Connect(hit.Activated, function()
		Library:PlaySound("Click")
		if obj.Callback then task.spawn(obj.Callback) end
	end)
	BindContext(hit, obj)

	function obj:SetText(t) lbl.Text = t; obj.Text = t end
	function obj:Press() if obj.Callback then task.spawn(obj.Callback) end end
	return obj
end

--=====================================================================
-- Label, paragraphe, séparateur
--=====================================================================

function Elements:AddLabel(text, opts)
	opts = opts or {}
	local holder = New("Frame", {
		Name = "LabelRow",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 24),
		AutomaticSize = opts.Wrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.None,
		LayoutOrder = self.NextOrder and self:NextOrder() or 0,
		Parent = self.Container,
	})
	TrackRow(self, holder, text)
	local lbl = Label(holder, text, opts.Size or 13, type(opts.Color) == "string" and opts.Color or "TextDim")
	if typeof(opts.Color) == "Color3" then Unregister(lbl, "TextColor3"); lbl.TextColor3 = opts.Color end
	if opts.Wrap then
		lbl.TextWrapped = true
		lbl.AutomaticSize = Enum.AutomaticSize.Y
		lbl.Size = UDim2.new(1, 0, 0, 0)
		lbl.TextYAlignment = Enum.TextYAlignment.Top
		Pad(holder, 3, 3, 0, 0)
	end
	if opts.Center then lbl.TextXAlignment = Enum.TextXAlignment.Center end
	local obj = { Type = "Label", Label = lbl }
	function obj:SetText(t) lbl.Text = tostring(t or "") end
	function obj:SetColor(c)
		if typeof(c) ~= "Color3" then return end
		Unregister(lbl, "TextColor3")
		lbl.TextColor3 = c
	end
	return obj
end

function Elements:AddParagraph(title, body)
	if type(title) == "table" then
		body = title.Content or title.Body or title.Text
		title = title.Title or ""
	end
	local holder = New("Frame", {
		Name = "Paragraph",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = self.NextOrder and self:NextOrder() or 0,
		Parent = self.Container,
	})
	Pad(holder, 6, 8, 0, 0)
	List(holder, 3)
	TrackRow(self, holder, tostring(title) .. " " .. tostring(body))
	local t = Label(holder, title, 13.5, "Text", Enum.FontWeight.SemiBold)
	t.Size = UDim2.new(1, 0, 0, 18)
	t.LayoutOrder = 1
	local b = Label(holder, body, 12.5, "TextDim")
	b.TextWrapped = true
	b.AutomaticSize = Enum.AutomaticSize.Y
	b.Size = UDim2.new(1, 0, 0, 0)
	b.TextYAlignment = Enum.TextYAlignment.Top
	b.LayoutOrder = 2
	local obj = { Type = "Paragraph" }
	function obj:SetTitle(v) t.Text = tostring(v) end
	function obj:SetBody(v) b.Text = tostring(v) end
	function obj:Set(v1, v2)
		if v1 ~= nil then t.Text = tostring(v1) end
		if v2 ~= nil then b.Text = tostring(v2) end
	end
	return obj
end

function Elements:AddDivider(text)
	local holder = New("Frame", {
		Name = "Divider",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, type(text) == "string" and 26 or 13),
		LayoutOrder = self.NextOrder and self:NextOrder() or 0,
		Parent = self.Container,
	})
	local line = New("Frame", {
		Size = UDim2.new(1, 0, 0, 1),
		Position = UDim2.fromScale(0, 0.5),
		AnchorPoint = Vector2.new(0, 0.5),
		BorderSizePixel = 0,
		Parent = holder,
	})
	Library:Register(line, { BackgroundColor3 = "BorderSoft" })
	if type(text) == "string" then
		local cap = Mono(holder, string.upper(text), 10, "TextFaint", Enum.FontWeight.SemiBold)
		cap.AutomaticSize = Enum.AutomaticSize.X
		cap.Size = UDim2.new(0, 0, 1, 0)
		cap.ZIndex = 3
		Library:Register(cap, { BackgroundColor3 = "Panel2" })
		cap.BackgroundTransparency = 0
		Pad(cap, 0, 0, 0, 8)
	end
	return { Type = "Divider" }
end

--=====================================================================
-- Slider
--=====================================================================

function Elements:AddSlider(flag, opts)
	opts = opts or {}
	local text     = opts.Text or opts.Name or flag
	local min      = opts.Min or 0
	local max      = opts.Max or 100
	local rounding = opts.Rounding or 0
	local suffix   = opts.Suffix or ""
	local default  = math.clamp(opts.Default or min, min, max)

	local row, lbl, addons, _, hover = WideRow(self, text, M.RowSlider, opts.Tooltip)

	-- Valeur : pastille éditable (clic pour taper une valeur exacte).
	local chip = New("Frame", {
		Name = "Value",
		Size = UDim2.fromOffset(0, 20),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = -1,
		ZIndex = 11,
		Parent = addons,
	})
	Library:Register(chip, { BackgroundColor3 = "Element" })
	Corner(chip, 5)
	local chipStroke = Stroke(chip, "BorderSoft")
	Pad(chip, 0, 0, 7, 7)
	local valueBox = New("TextBox", {
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.new(0, 0, 1, 0),
		Text = "",
		TextSize = TS(11.5),
		ClearTextOnFocus = false,
		TextXAlignment = Enum.TextXAlignment.Center,
		ZIndex = 12,
		Parent = chip,
	})
	SetFontRole(valueBox, "Mono", Enum.FontWeight.SemiBold)
	Library:Register(valueBox, { TextColor3 = "Text" })

	local track = New("Frame", {
		Name = "Track",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 0, 1, -10),
		Size = UDim2.new(1, 0, 0, 4),
		ZIndex = 3,
		Parent = row,
	})
	Library:Register(track, { BackgroundColor3 = "Track" })
	Corner(track, "full")

	local fill = New("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		BorderSizePixel = 0,
		ZIndex = 4,
		Parent = track,
	})
	Library:Register(fill, { BackgroundColor3 = "Accent" })
	Corner(fill, "full")

	local knob = New("Frame", {
		Name = "Knob",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(12, 12),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		ZIndex = 6,
		Parent = track,
	})
	Corner(knob, "full")
	local knobRing = New("UIStroke", { Thickness = 0, Transparency = 0.45, Parent = knob })
	Library:Register(knobRing, { Color = "Accent" })

	-- Bulle au-dessus du bouton pendant le glissement.
	local bubble = New("Frame", {
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 0, -8),
		Size = UDim2.fromOffset(0, 20),
		AutomaticSize = Enum.AutomaticSize.X,
		Visible = false,
		ZIndex = 30,
		Parent = knob,
	})
	Library:Register(bubble, { BackgroundColor3 = "Light" })
	Corner(bubble, 5)
	Pad(bubble, 0, 0, 7, 7)
	local bubbleText = Mono(bubble, "", 11, "OnLight", Enum.FontWeight.Bold)
	bubbleText.AutomaticSize = Enum.AutomaticSize.X
	bubbleText.Size = UDim2.new(0, 0, 1, 0)
	bubbleText.ZIndex = 31
	bubbleText.TextXAlignment = Enum.TextXAlignment.Center

	local obj = Bind({ Type = "Slider" }, flag, default)
	obj.Callback = opts.Callback
	obj.Text, obj.Row, obj.Min, obj.Max, obj.Rounding, obj.Suffix = text, row, min, max, rounding, suffix

	local function fmt(v) return tostring(Round(v, rounding)) .. suffix end

	local lastTick = 0
	local function paint(instant)
		local alpha = (max - min) == 0 and 0 or (obj.Value - min) / (max - min)
		local d = instant and 0 or 0.08
		Tween(fill, d, { Size = UDim2.fromScale(alpha, 1) })
		Tween(knob, d, { Position = UDim2.fromScale(alpha, 0.5) })
		if not valueBox:IsFocused() then valueBox.Text = fmt(obj.Value) end
		bubbleText.Text = fmt(obj.Value)
	end

	function obj:Set(value, silent)
		value = math.clamp(Round(tonumber(value) or min, rounding), min, max)
		local changed = value ~= obj.Value
		obj.Value = value
		if flag then Library.Flags[flag] = value end
		paint()
		if changed and not silent then
			if os.clock() - lastTick > 0.045 then
				lastTick = os.clock()
				Library:PlaySound("Tick", { Pitch = 0.85 + ((value - min) / math.max(max - min, 1e-6)) * 0.5 })
			end
			if obj.Callback then task.spawn(obj.Callback, value) end
		end
	end
	function obj:Get() return obj.Value end
	function obj:SetRange(newMin, newMax)
		min, max = newMin or min, newMax or max
		obj.Min, obj.Max = min, max
		obj:Set(obj.Value, true)
	end

	local dragging = false
	local function fromInput(input)
		local x = K.InputPos(input).X
		local a = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
		obj:Set(min + (max - min) * a)
	end

	local hit = Hit(track, "SliderHit", 8)
	hit.Size = UDim2.new(1, 12, 1, 22)
	hit.Position = UDim2.fromOffset(-6, -11)
	Library:Connect(hit.InputBegan, function(input)
		if IsClick(input) then
			dragging = true
			bubble.Visible = true
			Tween(knob, 0.15, { Size = UDim2.fromOffset(15, 15) }, Enum.EasingStyle.Back)
			Tween(knobRing, 0.15, { Thickness = 4 })
			fromInput(input)
		end
	end)
	Library:Connect(UserInputService.InputEnded, function(input)
		if dragging and IsClick(input) then
			dragging = false
			bubble.Visible = false
			Tween(knob, 0.2, { Size = UDim2.fromOffset(12, 12) }, Enum.EasingStyle.Back)
			Tween(knobRing, 0.2, { Thickness = 0 })
		end
	end)
	Library:Connect(UserInputService.InputChanged, function(input)
		if dragging and IsMove(input) then fromInput(input) end
	end)
	HoverRow(hit, lbl, hover, nil, function()
		if not dragging then Paint(lbl, 0.15, "TextColor3", "TextDim") end
	end)
	BindContext(hit, obj)

	Library:Connect(valueBox.Focused, function()
		valueBox.Text = tostring(Round(obj.Value, rounding))
		Paint(chipStroke, 0.12, "Color", "Accent")
	end)
	Library:Connect(valueBox.FocusLost, function()
		local n = tonumber((valueBox.Text:gsub("[^%d%.%-]", "")))
		if n then obj:Set(n) end
		valueBox.Text = fmt(obj.Value)
		Paint(chipStroke, 0.15, "Color", "BorderSoft")
	end)

	paint(true)
	if opts.Callback and opts.FireOnStart then task.spawn(opts.Callback, obj.Value) end
	return Addonable(obj, addons)
end

--=====================================================================
-- Popups (CanvasGroup : fondu d'un bloc et coins vraiment arrondis)
--=====================================================================

local function MakePopup(anchor, width, height)
	local function W() return type(width) == "function" and width() or width end
	local holder = New("Frame", {
		Name = "PopupHolder",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(W(), height),
		Visible = false,
		ZIndex = 510,
		Parent = PopupLayer,
	})
	local scale = New("UIScale", { Scale = Factor(), Parent = holder })
	Shadow(holder, 18, 0.45, 509)
	local popup = New("CanvasGroup", {
		Name = "Popup",
		Size = UDim2.fromScale(1, 1),
		GroupTransparency = 1,
		ZIndex = 510,
		Parent = holder,
	})
	Library:Register(popup, { BackgroundColor3 = "Panel2" })
	Corner(popup, 9)
	local border = New("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 540, Parent = holder })
	Corner(border, 9)
	Stroke(border, "Border")

	local slide = 0
	local function reposition()
		local o = PopupLayer.AbsolutePosition
		local ap, as = anchor.AbsolutePosition, anchor.AbsoluteSize
		local vp = ViewportSize()
		local f = Factor()
		local w, h = holder.Size.X.Offset * f, holder.Size.Y.Offset * f
		local x = math.clamp(ap.X - o.X, 6, math.max(vp.X - w - 6, 6))
		local y = ap.Y - o.Y + as.Y + 5
		if y + h > vp.Y - 6 then y = math.max(ap.Y - o.Y - h - 5, 6) end
		holder.Position = UDim2.fromOffset(x, y + slide * f)
	end

	local isOpen, follow = false, nil
	local closeFn
	local function close()
		if not isOpen then return end
		isOpen = false
		if follow then follow:Disconnect(); follow = nil end
		Tween(popup, 0.14, { GroupTransparency = 1 }, Enum.EasingStyle.Quad)
		border.Visible = false
		task.delay(0.15 * Library.Motion, function()
			if not isOpen then holder.Visible = false end
		end)
		if K.GetActivePopup() == closeFn then K.SetActivePopup(nil) end
	end
	closeFn = close

	local function open()
		K.CloseActivePopup()
		isOpen = true
		holder.Size = UDim2.fromOffset(W(), holder.Size.Y.Offset)
		scale.Scale = Factor()
		holder.Visible = true
		border.Visible = true
		popup.GroupTransparency = 1
		slide = -6
		reposition()
		Tween(popup, 0.2, { GroupTransparency = 0 }, Enum.EasingStyle.Quad)
		local t0 = os.clock()
		follow = RunService.RenderStepped:Connect(function()
			local a = math.clamp((os.clock() - t0) / (0.3 * Library.Motion), 0, 1)
			slide = -6 * (1 - a) ^ 3
			reposition()
		end)
		K.SetActivePopup(closeFn)
		Library:PlaySound("Popup")
	end

	local function toggle() if isOpen then close() else open() end end

	Library:Connect(UserInputService.InputBegan, function(input)
		if not isOpen or not IsClick(input) then return end
		local p = MousePos()
		if not K.PointInside(holder, p) and not K.PointInside(anchor, p) then close() end
	end)

	return popup, open, close, toggle, function() return isOpen end, holder
end
K.MakePopup = MakePopup

local function FieldBox(parent, width, height, radius)
	local box = New("Frame", {
		Name = "Field",
		Size = width and UDim2.fromOffset(width, height or M.Field) or UDim2.new(1, 0, 0, height or M.Field),
		ZIndex = 11,
		Parent = parent,
	})
	Library:Register(box, { BackgroundColor3 = "Element" })
	Corner(box, radius or 7)
	local stroke = Stroke(box, "BorderSoft")
	return box, stroke
end
K.FieldBox = FieldBox

local function SearchField(parent, placeholder, z)
	local sb = FieldBox(parent, nil, 28, 6)
	sb.ZIndex = z
	local ic = Icon(sb, "search", 13, "TextFaint", z + 1)
	ic.AnchorPoint = Vector2.new(0, 0.5)
	ic.Position = UDim2.new(0, 9, 0.5, 0)
	local box = New("TextBox", {
		BackgroundTransparency = 1,
		Text = "",
		PlaceholderText = placeholder or "Search…",
		TextSize = TS(12.5),
		TextXAlignment = Enum.TextXAlignment.Left,
		ClearTextOnFocus = false,
		Size = UDim2.new(1, -36, 1, 0),
		Position = UDim2.fromOffset(28, 0),
		ZIndex = z + 1,
		Parent = sb,
	})
	SetFontRole(box, "Text", Enum.FontWeight.Medium)
	Library:Register(box, { TextColor3 = "Text", PlaceholderColor3 = "TextFaint" })
	return box, sb
end
K.SearchField = SearchField

--=====================================================================
-- Liste déroulante
--=====================================================================

function Elements:AddDropdown(flag, opts)
	opts = opts or {}
	local text        = opts.Text or opts.Name or flag
	local multi       = opts.Multi == true
	local maxShow     = opts.MaxVisible or 7
	local placeholder = opts.Placeholder or "Select…"

	local row, lbl, addons, _, hover = WideRow(self, text, M.RowWide, opts.Tooltip)
	local box, boxStroke = FieldBox(row, nil, M.Field)
	box.AnchorPoint = Vector2.new(0, 1)
	box.Position = UDim2.new(0, 0, 1, -4)

	local display = Label(box, "", 13, "TextFaint")
	display.Position = UDim2.fromOffset(11, 0)
	display.Size = UDim2.new(1, -36, 1, 0)
	display.TextTruncate = Enum.TextTruncate.AtEnd
	display.ZIndex = 12
	local chev = Icon(box, "chevron", 14, "TextFaint", 13)
	chev.AnchorPoint = Vector2.new(1, 0.5)
	chev.Position = UDim2.new(1, -9, 0.5, 0)

	local default = multi and (opts.Default or {}) or opts.Default
	if multi and type(default) ~= "table" then default = { default } end
	if multi then default = table.clone(default) end
	local obj = Bind({ Type = "Dropdown" }, flag, default)
	obj.Callback = opts.Callback
	obj.Values = opts.Values or opts.Options or {}
	obj.Multi, obj.Text, obj.Row = multi, text, row

	local ROW_H = 30
	local popup, open, close, toggle, isOpen, holder = MakePopup(box, function()
		return math.max(box.AbsoluteSize.X / Factor(), 160)
	end, 40)

	local searchHolder = New("Frame", {
		Name = "Search", BackgroundTransparency = 1,
		Size = UDim2.new(1, -12, 0, 28), Position = UDim2.fromOffset(6, 6),
		Visible = false, ZIndex = 512, Parent = popup,
	})
	local searchBox = SearchField(searchHolder, "Search…", 512)

	local scroller = New("ScrollingFrame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 3,
		ScrollBarImageTransparency = 0.4,
		ZIndex = 511,
		Parent = popup,
	})
	Library:Register(scroller, { ScrollBarImageColor3 = "Border" })
	Pad(scroller, 5, 5, 5, 5)
	List(scroller, 1)

	local entries = {}
	local function isSelected(v)
		if multi then return table.find(obj.Value, v) ~= nil end
		return obj.Value == v
	end

	local function refreshDisplay()
		local txt
		if multi then
			local parts = {}
			for _, v in ipairs(obj.Value) do table.insert(parts, tostring(v)) end
			txt = #parts > 0 and table.concat(parts, ", ") or placeholder
		else
			txt = obj.Value ~= nil and tostring(obj.Value) or placeholder
		end
		display.Text = txt
		Paint(display, 0.12, "TextColor3", (txt == placeholder) and "TextFaint" or "Text")
		for value, e in pairs(entries) do
			local on = isSelected(value)
			Paint(e.Label, 0.12, "TextColor3", on and "Text" or "TextDim")
			Tween(e.Frame, 0.12, { BackgroundTransparency = on and 0 or 1 })
			Tween(e.Check, 0.12, { ImageTransparency = on and 0 or 1 })
		end
	end

	local function fire()
		if flag then Library.Flags[flag] = obj.Value end
		if obj.Callback then task.spawn(obj.Callback, obj.Value) end
	end

	local function sizePopup(count)
		local searchH = (#obj.Values > 8) and 38 or 0
		searchHolder.Visible = searchH > 0
		scroller.Position = UDim2.fromOffset(0, searchH)
		scroller.Size = UDim2.new(1, 0, 1, -searchH)
		local shown = math.min(math.max(count, 1), maxShow)
		holder.Size = UDim2.fromOffset(holder.Size.X.Offset, shown * (ROW_H + 1) + 10 + searchH)
	end

	local function applySearch()
		local q = string.lower(searchBox.Text or "")
		local n = 0
		for value, e in pairs(entries) do
			local ok = q == "" or string.find(string.lower(tostring(value)), q, 1, true) ~= nil
			e.Frame.Visible = ok
			if ok then n += 1 end
		end
		sizePopup(n)
	end

	local function build()
		for _, e in pairs(entries) do e.Frame:Destroy() end
		table.clear(entries)
		for i, value in ipairs(obj.Values) do
			local item = New("Frame", {
				Name = "Option",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, ROW_H),
				LayoutOrder = i,
				ZIndex = 512,
				Parent = scroller,
			})
			Library:Register(item, { BackgroundColor3 = "Element" })
			Corner(item, 6)
			local ol = Label(item, tostring(value), 13, "TextDim")
			ol.Position = UDim2.fromOffset(10, 0)
			ol.Size = UDim2.new(1, -36, 1, 0)
			ol.TextTruncate = Enum.TextTruncate.AtEnd
			ol.ZIndex = 513
			local check = Icon(item, "check", 14, "Accent", 514)
			check.AnchorPoint = Vector2.new(1, 0.5)
			check.Position = UDim2.new(1, -9, 0.5, 0)
			check.ImageTransparency = 1
			local h = Hit(item, "OptionHit", 515)
			Library:Connect(h.MouseEnter, function()
				if not isSelected(value) then Tween(item, 0.1, { BackgroundTransparency = 0.5 }) end
			end)
			Library:Connect(h.MouseLeave, function()
				Tween(item, 0.12, { BackgroundTransparency = isSelected(value) and 0 or 1 })
			end)
			Library:Connect(h.MouseButton1Click, function()
				if multi then
					local idx = table.find(obj.Value, value)
					if idx then table.remove(obj.Value, idx) else table.insert(obj.Value, value) end
					Library:PlaySound(idx and "ToggleOff" or "ToggleOn")
				else
					if obj.Value == value and opts.AllowNull then obj.Value = nil else obj.Value = value end
					Library:PlaySound("Click")
					close()
				end
				refreshDisplay()
				fire()
			end)
			entries[value] = { Frame = item, Label = ol, Check = check }
		end
		applySearch()
	end

	function obj:Set(value, silent)
		if multi then
			if type(value) ~= "table" then value = value ~= nil and { value } or {} end
			value = table.clone(value)
		end
		obj.Value = value
		refreshDisplay()
		if flag then Library.Flags[flag] = obj.Value end
		if not silent and obj.Callback then task.spawn(obj.Callback, obj.Value) end
	end
	function obj:Get() return obj.Value end
	function obj:SetValues(newValues, keep)
		obj.Values = newValues or {}
		build()
		if not keep then obj.Value = multi and {} or nil end
		refreshDisplay()
	end
	obj.Refresh = obj.SetValues

	Library:Connect(searchBox:GetPropertyChangedSignal("Text"), applySearch)

	local h = Hit(box, "DropdownHit", 14)
	Library:Connect(h.MouseButton1Click, function()
		if not isOpen() then searchBox.Text = "" end
		toggle()
		Tween(chev, 0.22, { Rotation = isOpen() and 180 or 0 })
		Paint(boxStroke, 0.15, "Color", isOpen() and "Accent" or "BorderSoft")
	end)
	HoverRow(h, lbl, hover, function()
		Paint(box, 0.12, "BackgroundColor3", "ElementHover")
	end, function()
		Paint(box, 0.15, "BackgroundColor3", "Element")
		Paint(lbl, 0.15, "TextColor3", "TextDim")
	end)
	BindContext(h, obj)
	Library:Connect(holder:GetPropertyChangedSignal("Visible"), function()
		if not holder.Visible then
			Tween(chev, 0.2, { Rotation = 0 })
			Paint(boxStroke, 0.15, "Color", "BorderSoft")
		end
	end)

	build()
	refreshDisplay()
	return Addonable(obj, addons)
end

--=====================================================================
-- Champ texte
--=====================================================================

function Elements:AddTextbox(flag, opts)
	opts = opts or {}
	local text = opts.Text or opts.Name or flag
	local row, lbl, addons, hover = CompactRow(self, text, M.Row + 2, opts.Tooltip)
	local box, stroke = FieldBox(addons, opts.Width or M.FieldW, M.Field - 2, 6)

	local input = New("TextBox", {
		BackgroundTransparency = 1,
		Text = opts.Default or "",
		PlaceholderText = opts.Placeholder or "…",
		TextSize = TS(13),
		TextXAlignment = Enum.TextXAlignment.Left,
		ClearTextOnFocus = opts.ClearOnFocus == true,
		Size = UDim2.new(1, -18, 1, 0),
		Position = UDim2.fromOffset(9, 0),
		ClipsDescendants = true,
		ZIndex = 12,
		Parent = box,
	})
	SetFontRole(input, "Text", Enum.FontWeight.Medium)
	Library:Register(input, { TextColor3 = "Text", PlaceholderColor3 = "TextFaint" })

	local obj = Bind({ Type = "Textbox" }, flag, opts.Default or "")
	obj.Callback, obj.Text, obj.Row = opts.Callback, text, row

	function obj:Set(value, silent)
		obj.Value = tostring(value or "")
		input.Text = obj.Value
		if flag then Library.Flags[flag] = obj.Value end
		if not silent and obj.Callback then task.spawn(obj.Callback, obj.Value) end
	end
	function obj:Get() return obj.Value end

	Library:Connect(input.FocusLost, function(enter)
		obj.Value = input.Text
		if flag then Library.Flags[flag] = obj.Value end
		if obj.Callback then task.spawn(obj.Callback, obj.Value, enter) end
		Paint(stroke, 0.15, "Color", "BorderSoft")
		Paint(lbl, 0.15, "TextColor3", "TextDim")
	end)
	Library:Connect(input.Focused, function()
		Paint(stroke, 0.15, "Color", "Accent")
		Paint(lbl, 0.15, "TextColor3", "Text")
	end)
	return Addonable(obj, addons)
end
Elements.AddInput = Elements.AddTextbox

--=====================================================================
-- Raccourci
--=====================================================================

local KeybindRegistry = {}
K.KeybindRegistry = KeybindRegistry

local KEY_ALIAS = {
	LeftShift = "LShift", RightShift = "RShift", LeftControl = "LCtrl", RightControl = "RCtrl",
	LeftAlt = "LAlt", RightAlt = "RAlt", MouseButton1 = "MB1", MouseButton2 = "MB2", MouseButton3 = "MB3",
	Backspace = "Bksp", Return = "Enter", Escape = "Esc", Space = "Space",
}

local function KeyName(key)
	if key == nil then return "None" end
	local name = typeof(key) == "EnumItem" and key.Name or tostring(key)
	return KEY_ALIAS[name] or name
end
Library.KeyName = KeyName

local function BuildKeybind(parent, flag, opts, withLabel)
	opts = opts or {}
	local modes = opts.Modes or { "Always", "Toggle", "Hold" }

	local box, stroke = FieldBox(parent, nil, (withLabel and M.Field or M.Field - 4) - 6, 6)
	box.Size = UDim2.fromOffset(0, box.Size.Y.Offset)
	box.AutomaticSize = Enum.AutomaticSize.X
	box.LayoutOrder = 700
	local under = New("Frame", {
		AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, 2), BorderSizePixel = 0, ZIndex = 11, Parent = box,
	})
	Library:Register(under, { BackgroundColor3 = "BorderSoft" })
	Pad(box, 0, 0, 9, 9)
	local display = Mono(box, "", 11, "TextDim", Enum.FontWeight.SemiBold)
	display.AutomaticSize = Enum.AutomaticSize.X
	display.Size = UDim2.new(0, math.max((opts.Width or M.KeybindW) - 18, 18), 1, 0)
	display.TextXAlignment = Enum.TextXAlignment.Center
	display.ZIndex = 12

	local obj = Bind({ Type = "Keybind" }, flag, { Key = opts.Default, Mode = opts.Mode or modes[1] })
	obj.Callback, obj.Changed, obj.Modes, obj.Active = opts.Callback, opts.Changed, modes, false
	obj.Text = opts.Text or opts.Name or flag

	local listening = false
	local function paint()
		display.Text = listening and "…" or string.upper(KeyName(obj.Value.Key))
		Paint(display, 0.12, "TextColor3", listening and "Accent" or (obj.Value.Key and "Text" or "TextFaint"))
		Paint(stroke, 0.12, "Color", listening and "Accent" or "BorderSoft")
	end

	function obj:Set(value, silent)
		if typeof(value) == "EnumItem" or type(value) == "string" then
			value = { Key = value, Mode = obj.Value.Mode }
		end
		obj.Value = {
			Key = value and value.Key or nil,
			Mode = (value and value.Mode) or obj.Value.Mode or modes[1],
		}
		if flag then Library.Flags[flag] = obj.Value end
		paint()
		if not silent and obj.Changed then task.spawn(obj.Changed, obj.Value) end
	end
	function obj:Get() return obj.Value end
	function obj:GetState()
		if not obj.Value.Key then return false end
		if obj.Value.Mode == "Always" then return true end
		return obj.Active
	end

	-- Menu des modes (clic droit).
	local modePopup, _, closeModes, toggleModes = MakePopup(box, 120, #modes * 29 + 10)
	local ml = New("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 512, Parent = modePopup })
	Pad(ml, 5, 5, 5, 5)
	List(ml, 1)
	local modeRows = {}
	for i, mode in ipairs(modes) do
		local it = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 28), LayoutOrder = i, ZIndex = 512, Parent = ml })
		Library:Register(it, { BackgroundColor3 = "Element" })
		Corner(it, 6)
		local t = Label(it, mode, 12.5, "TextDim")
		t.Position = UDim2.fromOffset(9, 0)
		t.ZIndex = 513
		local hh = Hit(it, "Mode", 514)
		Library:Connect(hh.MouseButton1Click, function()
			obj:Set({ Key = obj.Value.Key, Mode = mode })
			Library:PlaySound("Click")
			closeModes()
		end)
		Library:Connect(hh.MouseEnter, function() Tween(it, 0.1, { BackgroundTransparency = 0.4 }) end)
		Library:Connect(hh.MouseLeave, function() Tween(it, 0.1, { BackgroundTransparency = 1 }) end)
		modeRows[mode] = t
	end

	local h = Hit(box, "KeybindHit", 14)
	Library:Connect(h.MouseButton1Click, function()
		if not UserInputService.KeyboardEnabled then
			Library:Notify({ Title = obj.Text, Content = "No keyboard on this device.", Duration = 2 })
			return
		end
		listening = true
		Library:PlaySound("Click")
		paint()
	end)
	Library:Connect(h.MouseButton2Click, function()
		for mode, t in pairs(modeRows) do
			t.TextColor3 = mode == obj.Value.Mode and Theme.Accent or Theme.TextDim
		end
		toggleModes()
	end)
	Library:Connect(h.MouseEnter, function()
		Paint(box, 0.12, "BackgroundColor3", "ElementHover")
		Library:ShowTooltip(opts.Tooltip or "Click: assign  ·  Right click: mode  ·  Backspace: clear")
	end)
	Library:Connect(h.MouseLeave, function()
		Paint(box, 0.12, "BackgroundColor3", "Element")
		Library:HideTooltip()
	end)

	local blink = 0
	Library:Connect(RunService.Heartbeat, function(dt)
		if not listening then return end
		blink += dt
		display.TextTransparency = (math.floor(blink * 4) % 2 == 0) and 0 or 0.5
	end)

	Library:Connect(UserInputService.InputBegan, function(input, processed)
		if listening then
			local key
			if input.UserInputType == Enum.UserInputType.Keyboard then
				key = input.KeyCode
			elseif input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.MouseButton2
				or input.UserInputType == Enum.UserInputType.MouseButton3 then
				-- Le clic qui a lancé l'écoute ne compte pas.
				if K.PointInside(box, MousePos()) then return end
				key = input.UserInputType
			end
			if key then
				listening = false
				display.TextTransparency = 0
				if key == Enum.KeyCode.Backspace or key == Enum.KeyCode.Escape then
					obj:Set({ Key = nil, Mode = obj.Value.Mode })
				else
					obj:Set({ Key = key, Mode = obj.Value.Mode })
					FX.Pulse(box, Theme.Accent, 2)
				end
			end
			return
		end
		if processed or not obj.Value.Key then return end
		local matches = (input.KeyCode == obj.Value.Key) or (input.UserInputType == obj.Value.Key)
		if not matches then return end
		if obj.Value.Mode == "Toggle" then obj.Active = not obj.Active else obj.Active = true end
		if obj.Callback then task.spawn(obj.Callback, obj:GetState()) end
	end)
	Library:Connect(UserInputService.InputEnded, function(input)
		if not obj.Value.Key or obj.Value.Mode ~= "Hold" then return end
		if (input.KeyCode == obj.Value.Key) or (input.UserInputType == obj.Value.Key) then
			obj.Active = false
			if obj.Callback then task.spawn(obj.Callback, false) end
		end
	end)

	obj.DisplayName = opts.Text or opts.Name or flag or "Keybind"
	table.insert(KeybindRegistry, obj)
	paint()
	return obj
end

function Elements:AddKeybind(flag, opts)
	opts = opts or {}
	local _, _, addons = CompactRow(self, opts.Text or opts.Name or flag, M.Row, opts.Tooltip)
	local obj = BuildKeybind(addons, flag, opts, true)
	return Addonable(obj, addons)
end

MiniKeybind = function(holder, flag, opts)
	return BuildKeybind(holder, flag, opts, false)
end

--=====================================================================
-- Sélecteur de couleur
--=====================================================================

local RAINBOW = ColorSequence.new({
	ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 0, 0)),
	ColorSequenceKeypoint.new(0.17, Color3.fromRGB(255, 255, 0)),
	ColorSequenceKeypoint.new(0.33, Color3.fromRGB(0, 255, 0)),
	ColorSequenceKeypoint.new(0.50, Color3.fromRGB(0, 255, 255)),
	ColorSequenceKeypoint.new(0.67, Color3.fromRGB(0, 0, 255)),
	ColorSequenceKeypoint.new(0.83, Color3.fromRGB(255, 0, 255)),
	ColorSequenceKeypoint.new(1.00, Color3.fromRGB(255, 0, 0)),
})

local function BuildColorPicker(parent, flag, opts)
	opts = opts or {}
	local useAlpha = opts.Alpha == true or opts.Transparency ~= nil

	local swatch = New("Frame", {
		Name = "Swatch",
		Size = UDim2.fromOffset(opts.Width or M.Swatch, M.SwatchH),
		BackgroundColor3 = opts.Default or Theme.Accent,
		LayoutOrder = 600,
		ZIndex = 11,
		Parent = parent,
	})
	Corner(swatch, 5)
	New("UIStroke", { Color = Color3.new(1, 1, 1), Transparency = 0.82, Parent = swatch })

	local obj = Bind({ Type = "ColorPicker" }, flag, opts.Default or Theme.Accent)
	obj.Alpha = opts.DefaultAlpha or (opts.Transparency and 1 - opts.Transparency) or 1
	obj.Callback = opts.Callback
	obj.Text = opts.Text or opts.Name or flag

	local h, s, v = Color3.toHSV(obj.Value)
	local SVH = 120
	local popH = 12 + SVH + 10 + (useAlpha and 22 or 0) + 30 + 8 + 22 + 12
	local popup, _, _, toggle = MakePopup(swatch, 224, popH)

	local body = New("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 511, Parent = popup })
	Pad(body, 12, 12, 12, 12)
	List(body, 10)

	local top = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, SVH), LayoutOrder = 1, ZIndex = 511, Parent = body })
	local sv = New("Frame", { Size = UDim2.new(1, -24, 1, 0), BorderSizePixel = 0, ZIndex = 512, Parent = top })
	Corner(sv, 6)
	local white = New("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 513, Parent = sv })
	Corner(white, 6)
	New("UIGradient", { Transparency = NSeq({ { 0, 0 }, { 1, 1 } }), Parent = white })
	local black = New("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0, ZIndex = 514, Parent = sv })
	Corner(black, 6)
	New("UIGradient", { Rotation = 90, Transparency = NSeq({ { 0, 1 }, { 1, 0 } }), Parent = black })
	local svCursor = New("Frame", { Size = UDim2.fromOffset(12, 12), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1, ZIndex = 516, Parent = sv })
	Corner(svCursor, "full")
	New("UIStroke", { Thickness = 2, Color = Color3.new(1, 1, 1), Parent = svCursor })

	local hue = New("Frame", { Size = UDim2.new(0, 12, 1, 0), Position = UDim2.new(1, -12, 0, 0), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 512, Parent = top })
	Corner(hue, "full")
	New("UIGradient", { Color = RAINBOW, Rotation = 90, Parent = hue })
	local hueCursor = New("Frame", { Size = UDim2.new(1, 4, 0, 4), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0, 0), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 515, Parent = hue })
	Corner(hueCursor, "full")

	local alphaBar, alphaCursor, alphaGrad
	if useAlpha then
		alphaBar = New("Frame", { Size = UDim2.new(1, 0, 0, 12), LayoutOrder = 2, BackgroundColor3 = Color3.fromRGB(40, 40, 46), BorderSizePixel = 0, ZIndex = 512, Parent = body })
		Corner(alphaBar, "full")
		alphaGrad = New("UIGradient", { Color = ColorSequence.new(obj.Value), Transparency = NSeq({ { 0, 1 }, { 1, 0 } }), Parent = alphaBar })
		alphaCursor = New("Frame", { Size = UDim2.new(0, 4, 1, 4), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(1, 0, 0.5, 0), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 513, Parent = alphaBar })
		Corner(alphaCursor, "full")
	end

	local hexBox = FieldBox(body, nil, 30, 6)
	hexBox.LayoutOrder = 3
	hexBox.ZIndex = 512
	local hexInput = New("TextBox", {
		BackgroundTransparency = 1, Text = "#FFFFFF", TextSize = TS(12.5),
		Size = UDim2.new(1, -18, 1, 0), Position = UDim2.fromOffset(9, 0),
		TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false, ZIndex = 513, Parent = hexBox,
	})
	SetFontRole(hexInput, "Mono", Enum.FontWeight.Medium)
	Library:Register(hexInput, { TextColor3 = "Text" })

	-- Nuances du thème en un clic.
	local presets = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 22), LayoutOrder = 4, ZIndex = 512, Parent = body })
	List(presets, 6, Enum.FillDirection.Horizontal, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)

	local function apply(silent)
		obj.Value = Color3.fromHSV(h, s, v)
		swatch.BackgroundColor3 = obj.Value
		sv.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
		svCursor.Position = UDim2.fromScale(s, 1 - v)
		hueCursor.Position = UDim2.new(0.5, 0, h, 0)
		hexInput.Text = "#" .. obj.Value:ToHex():upper()
		if alphaGrad then
			alphaGrad.Color = ColorSequence.new(obj.Value)
			alphaCursor.Position = UDim2.new(obj.Alpha, 0, 0.5, 0)
		end
		if flag then
			Library.Flags[flag] = obj.Value
			Library.Flags[flag .. "_Alpha"] = obj.Alpha
		end
		if not silent and obj.Callback then task.spawn(obj.Callback, obj.Value, obj.Alpha) end
	end

	for i, p in ipairs(Library.Presets) do
		local dot = New("Frame", { Size = UDim2.fromOffset(20, 20), BackgroundColor3 = p.Accent, LayoutOrder = i, ZIndex = 513, Parent = presets })
		Corner(dot, "full")
		New("UIStroke", { Color = Color3.new(1, 1, 1), Transparency = 0.85, Parent = dot })
		local dh = Hit(dot, "Preset", 514)
		Library:Connect(dh.MouseButton1Click, function()
			h, s, v = Color3.toHSV(p.Accent)
			Library:PlaySound("Click")
			apply()
		end)
	end

	function obj:Set(color, alpha, silent)
		if typeof(color) == "Color3" then h, s, v = Color3.toHSV(color) end
		if type(alpha) == "number" then obj.Alpha = math.clamp(alpha, 0, 1) end
		if type(alpha) == "boolean" then silent = alpha end
		apply(silent)
	end
	function obj:Get() return obj.Value, obj.Alpha end
	function obj:SetValueRGB(c) obj:Set(c) end

	local function bindDrag(gui, onMove)
		local dragging = false
		local hh = Hit(gui, "PickHit", 520)
		Library:Connect(hh.InputBegan, function(input)
			if IsClick(input) then dragging = true; onMove(input) end
		end)
		Library:Connect(UserInputService.InputEnded, function(input)
			if IsClick(input) then dragging = false end
		end)
		Library:Connect(UserInputService.InputChanged, function(input)
			if dragging and IsMove(input) then onMove(input) end
		end)
	end
	bindDrag(sv, function(input)
		local p = K.InputPos(input)
		s = math.clamp((p.X - sv.AbsolutePosition.X) / math.max(sv.AbsoluteSize.X, 1), 0, 1)
		v = 1 - math.clamp((p.Y - sv.AbsolutePosition.Y) / math.max(sv.AbsoluteSize.Y, 1), 0, 1)
		apply()
	end)
	bindDrag(hue, function(input)
		local p = K.InputPos(input)
		h = math.clamp((p.Y - hue.AbsolutePosition.Y) / math.max(hue.AbsoluteSize.Y, 1), 0, 0.999)
		apply()
	end)
	if useAlpha then
		bindDrag(alphaBar, function(input)
			local p = K.InputPos(input)
			obj.Alpha = math.clamp((p.X - alphaBar.AbsolutePosition.X) / math.max(alphaBar.AbsoluteSize.X, 1), 0, 1)
			apply()
		end)
	end
	Library:Connect(hexInput.FocusLost, function()
		local ok, c = pcall(Color3.fromHex, (hexInput.Text:gsub("#", "")))
		if ok and c then h, s, v = Color3.toHSV(c) end
		apply()
	end)

	local sh = Hit(swatch, "SwatchHit", 14)
	Library:Connect(sh.MouseButton1Click, toggle)
	TipOn(sh, opts.Tooltip)
	apply(true)
	return obj
end

function Elements:AddColorPicker(flag, opts)
	opts = opts or {}
	local _, _, addons = CompactRow(self, opts.Text or opts.Name or flag, M.Row, opts.Tooltip)
	local obj = BuildColorPicker(addons, flag, opts)
	return Addonable(obj, addons)
end

MiniColorPicker = function(holder, flag, opts)
	return BuildColorPicker(holder, flag, opts)
end

--=====================================================================
-- Groupe
--=====================================================================

local Group = {}
Group.__index = setmetatable(Group, { __index = Elements })
K.Group = Group

function Group:NextOrder()
	self._order = (self._order or 0) + 1
	return self._order
end

local function CreateGroup(page, title, side, opts)
	opts = opts or {}
	local column = (side == "Right" or side == 2) and page.Right or page.Left

	-- Hauteur recopiée de la pile (pas d'AutomaticSize : le halo qui suit la souris l'agrandirait).
	local frame = New("Frame", {
		Name = "Group",
		Size = UDim2.new(1, 0, 0, M.Header),
		ClipsDescendants = true,
		LayoutOrder = #page.Groups + 1,
		Parent = column,
	})
	Library:Register(frame, { BackgroundColor3 = "Panel2" })
	Corner(frame, 10)
	local stroke = Stroke(frame, "BorderSoft")
	-- La pile (en-tête + corps) porte la UIListLayout ; les calques d'effet restent à côté.
	local stack = New("Frame", {
		Name = "Stack",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		ZIndex = 2,
		Parent = frame,
	})
	List(stack, 0)

	local header = New("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, M.Header),
		BackgroundTransparency = 1,
		LayoutOrder = 0,
		ZIndex = 2,
		Parent = stack,
	})
	local titleLabel = Label(header, title or "Group", 13.5, "Text", Enum.FontWeight.SemiBold)
	titleLabel.Position = UDim2.fromOffset(14, 0)
	titleLabel.Size = UDim2.new(1, -90, 1, 0)
	titleLabel.TextTruncate = Enum.TextTruncate.AtEnd
	titleLabel.ZIndex = 3

	local right = New("Frame", {
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -12, 0.5, 0),
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		ZIndex = 4,
		Parent = header,
	})
	List(right, 8, Enum.FillDirection.Horizontal, Enum.HorizontalAlignment.Right, Enum.VerticalAlignment.Center)

	local count = Mono(right, "", 10.5, "TextFaint")
	count.AutomaticSize = Enum.AutomaticSize.X
	count.Size = UDim2.new(0, 0, 1, 0)
	count.LayoutOrder = 1
	count.ZIndex = 4

	local chev = Icon(right, "chevron", 13, "TextFaint", 5)
	chev.LayoutOrder = 3

	local sep = New("Frame", {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 14, 1, 0),
		Size = UDim2.new(1, -28, 0, 1),
		BorderSizePixel = 0,
		ZIndex = 2,
		Parent = header,
	})
	Library:Register(sep, { BackgroundColor3 = "BorderSoft" })

	local body = New("Frame", {
		Name = "Body",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		ZIndex = 2,
		Parent = stack,
	})
	local container = New("Frame", {
		Name = "Container",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		ZIndex = 2,
		Parent = body,
	})
	Pad(container, 6, 10, M.GroupPad + 2, M.GroupPad + 2)
	List(container, M.RowGap)

	local function fitHeight()
		local ratio = M.Header / math.max(header.AbsoluteSize.Y, 1)
		frame.Size = UDim2.new(1, 0, 0, math.ceil(stack.AbsoluteSize.Y * ratio))
	end
	Library:Connect(stack:GetPropertyChangedSignal("AbsoluteSize"), fitHeight)
	task.defer(fitHeight)

	local self = setmetatable({
		Frame = frame, Container = container, Header = header, Title = titleLabel,
		Page = page, Rows = {}, Name = title,
	}, Group)
	table.insert(page.Groups, self)

	-- Halo discret qui suit la souris sur le groupe survolé.
	local spotClip = New("Frame", { Name = "Spot", BackgroundTransparency = 1, ClipsDescendants = true, Size = UDim2.fromScale(1, 1), ZIndex = 1, Parent = frame })
	local spot = FxImage(spotClip, "glow", 1)
	spot.AnchorPoint = Vector2.new(0.5, 0.5)
	spot.Size = UDim2.fromOffset(320, 320)
	spot.ImageTransparency = 1
	local spotConn
	local hoverSense = New("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 1, Parent = frame })
	Library:Connect(hoverSense.MouseEnter, function()
		Paint(stroke, 0.2, "Color", "Border")
		if not Library.Effects or spotConn then return end
		Tween(spot, 0.3, { ImageTransparency = 0.965 })
		spotConn = RunService.RenderStepped:Connect(function()
			local p = MousePos()
			local f = math.max(Factor(), 0.01)
			local a = frame.AbsolutePosition
			spot.Position = UDim2.fromOffset((p.X - a.X) / f, (p.Y - a.Y) / f)
		end)
	end)
	Library:Connect(hoverSense.MouseLeave, function()
		Paint(stroke, 0.25, "Color", "BorderSoft")
		Tween(spot, 0.25, { ImageTransparency = 1 })
		if spotConn then spotConn:Disconnect(); spotConn = nil end
	end)

	-- Repli par clic sur l'en-tête.
	local collapsed = false
	local headHit = Hit(header, "Collapse", 3)
	headHit.Size = UDim2.new(1, -60, 1, 0)
	local function setCollapsed(v)
		collapsed = v
		body.Visible = not v
		sep.Visible = not v
		Tween(chev, 0.25, { Rotation = v and -90 or 0 })
	end
	Library:Connect(headHit.MouseButton1Click, function()
		setCollapsed(not collapsed)
		Library:PlaySound("Click", { Pitch = collapsed and 0.9 or 1.05 })
	end)
	local chevHit = Hit(chev, "ChevHit", 6)
	Library:Connect(chevHit.MouseButton1Click, function()
		setCollapsed(not collapsed)
		Library:PlaySound("Click")
	end)

	-- Compteur : nombre d'options du groupe.
	function self.UpdateCount()
		local n = 0
		for _, r in ipairs(self.Rows) do if r.Frame.Name == "Row" then n += 1 end end
		count.Text = n > 0 and tostring(n) or ""
	end

	-- Apparition : le groupe remonte de quelques pixels, un filet le balaie.
	local veil = New("Frame", {
		Name = "Fader", BackgroundTransparency = 1, BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1), ZIndex = 60, Parent = frame,
	})
	Library:Register(veil, { BackgroundColor3 = "Panel2" })
	function self:Animate(delay)
		if not Library.Effects then return end
		veil.BackgroundTransparency = 0
		Tween(veil, 0.35, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad, nil, delay or 0)
		FX.Sweep(header, (delay or 0) + 0.05, 0.7, 0.9)
	end

	if opts.Toggle ~= nil or opts.Flag then
		local flag = opts.Flag
		local cover = New("Frame", {
			Name = "Veil", BackgroundTransparency = 1, Active = false, Visible = false,
			Size = UDim2.fromScale(1, 1), ZIndex = 40, Parent = body,
		})
		Library:Register(cover, { BackgroundColor3 = "Panel2" })
		local holder = New("Frame", {
			BackgroundTransparency = 1, Size = UDim2.fromOffset(M.SwitchW, M.SwitchH),
			LayoutOrder = 2, ZIndex = 5, Parent = right,
		})
		local track, setVisual = Switch(holder)
		count.Visible = false
		local state = opts.Toggle == true
		local function paint(instant)
			setVisual(state, instant)
			cover.Active = not state
			if state then
				Tween(cover, instant and 0 or 0.15, { BackgroundTransparency = 1 })
				task.delay(0.17, function() if state then cover.Visible = false end end)
			else
				cover.Visible = true
				Tween(cover, instant and 0 or 0.15, { BackgroundTransparency = 0.4 })
			end
		end
		local gobj = { Type = "Toggle", Text = title, Value = state, Default = state }
		function gobj:Get() return state end
		function gobj:Set(v, silent)
			state = v and true or false
			gobj.Value = state
			paint()
			if flag then Library.Flags[flag] = state end
			if not silent then
				Library:PlaySound(state and "ToggleOn" or "ToggleOff")
				if opts.Callback then task.spawn(opts.Callback, state) end
			end
		end
		local hh = Hit(holder, "GroupToggle", 14)
		Library:Connect(hh.MouseButton1Click, function() gobj:Set(not state) end)
		paint(true)
		if flag then
			gobj.Flag = flag
			Library.Flags[flag] = state
			Library.Options[flag] = gobj
		end
		self.Toggle = gobj
	end

	function self:SetTitle(t) titleLabel.Text = tostring(t); self.Name = t end
	function self:Destroy() frame:Destroy() end
	function self:SetCollapsed(v) setCollapsed(v and true or false) end
	return self
end
