function Tab:AddPage(name)
	local tab = self
	local button = New("TextButton", {
		Name = "Page_" .. name,
		Text = "",
		AutoButtonColor = false,
		BackgroundTransparency = 1,
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = #tab.Pages + 1,
		ZIndex = 22,
		Parent = tab.PageRow,
	})
	Pad(button, 0, 0, 10, 10)
	local btnLabel = Label(button, name, 13, "TextFaint", Enum.FontWeight.SemiBold)
	btnLabel.AutomaticSize = Enum.AutomaticSize.X
	btnLabel.Size = UDim2.new(0, 0, 1, 0)
	btnLabel.TextXAlignment = Enum.TextXAlignment.Center
	btnLabel.ZIndex = 23

	local content = New("Frame", {
		Name = "Page_" .. name,
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Visible = false,
		Parent = tab.PagesHolder,
	})

	local single = M.Columns == 1
	local function column(x)
		local col = New("ScrollingFrame", {
			Name = x == 0 and "Left" or "Right",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = single and UDim2.fromScale(1, 1) or UDim2.new(0.5, -6, 1, 0),
			Position = single and UDim2.new() or UDim2.new(x, x == 0 and 0 or 6, 0, 0),
			CanvasSize = UDim2.new(),
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			ScrollBarThickness = 3,
			ScrollBarImageTransparency = 0.5,
			ScrollingDirection = Enum.ScrollingDirection.Y,
			Parent = content,
		})
		Library:Register(col, { ScrollBarImageColor3 = "Border" })
		List(col, 12)
		Pad(col, 1, 14, 1, 5)
		return col
	end
	local left = column(0)
	local right = single and left or column(0.5)
	local columns = { { Frame = left, Base = left.Position, Delay = 0 } }
	if not single then table.insert(columns, { Frame = right, Base = right.Position, Delay = 0.05 }) end

	local page = setmetatable({
		Name = name, Content = content, Left = left, Right = right,
		Button = button, Label = btnLabel, Tab = tab, Groups = {},
	}, Page)

	local function playIn()
		for _, c in ipairs(columns) do
			c.Frame.Position = c.Base + UDim2.fromOffset(0, 10)
			TweenService:Create(c.Frame, TweenInfo.new(0.45 * Library.Motion, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out, 0, false, c.Delay * Library.Motion), { Position = c.Base }):Play()
		end
	end

	local function select(silent)
		if tab.ActivePage == page and content.Visible then return end
		for _, other in ipairs(tab.Pages) do
			other.Content.Visible = false
			Paint(other.Label, 0.15, "TextColor3", "TextFaint")
		end
		content.Visible = true
		playIn()
		Paint(btnLabel, 0.15, "TextColor3", "Text")
		tab.ActivePage = page
		if tab.MoveUnderline then tab.MoveUnderline(button) end
		for i, g in ipairs(page.Groups) do g:Animate((i - 1) * 0.05) end
		if tab.Window and tab.Window.ApplySearch then tab.Window:ApplySearch() end
		if tab.Window and tab.Window.UpdateCrumb then tab.Window.UpdateCrumb() end
		if not silent then Library:PlaySound("Tab", { Pitch = 1.1 }) end
	end
	page.Select = select

	Library:Connect(button.MouseButton1Click, function() select() end)
	Library:Connect(button.MouseEnter, function()
		if tab.ActivePage ~= page then Paint(btnLabel, 0.1, "TextColor3", "TextDim") end
	end)
	Library:Connect(button.MouseLeave, function()
		if tab.ActivePage ~= page then Paint(btnLabel, 0.1, "TextColor3", "TextFaint") end
	end)

	table.insert(tab.Pages, page)
	if tab.RefreshPages then tab.RefreshPages() end
	if #tab.Pages == 1 then
		task.defer(function() if not tab.ActivePage then select(true) end end)
	end
	return page
end
Tab.AddSection = Tab.AddPage
Tab.AddSubTab = Tab.AddPage

function Tab:AddGroup(title, side, opts)
	if #self.Pages == 0 then self:AddPage("Main") end
	return self.Pages[1]:AddGroup(title, side, opts)
end
Tab.AddGroupbox = Tab.AddGroup
function Tab:AddLeftGroupbox(title) return self:AddGroup(title, "Left") end
function Tab:AddRightGroupbox(title) return self:AddGroup(title, "Right") end

function Tab:CountRows()
	local n = 0
	for _, p in ipairs(self.Pages) do
		for _, g in ipairs(p.Groups) do
			for _, r in ipairs(g.Rows) do if r.Frame.Name == "Row" then n += 1 end end
		end
	end
	return n
end

