	{ { "farm", "auto", "main", "home", "general" }, "home" },
	{ { "combat", "fight", "pvp", "kill", "attack", "battle", "boss" }, "sword" },
	{ { "aim", "target", "silent" }, "crosshair" },
	{ { "visual", "esp", "render" }, "eye" },
	{ { "player", "local", "character", "self" }, "user" },
	{ { "world", "teleport", "tp", "map", "server" }, "globe" },
	{ { "setting", "config", "option", "ui", "menu" }, "gear" },
	{ { "move", "movement", "speed", "fly" }, "bolt" },
	{ { "item", "inventory", "loot", "shop", "chest", "craft", "dungeon" }, "layers" },
	{ { "premium", "vip" }, "crown" },
	{ { "key", "credit", "info", "about" }, "key" },
	{ { "misc", "other", "extra", "util" }, "star" },
}
local function AutoIcon(name)
	local n = string.lower(tostring(name or ""))
	for _, e in ipairs(AUTO_ICONS) do
		for _, key in ipairs(e[1]) do
			if string.find(n, key, 1, true) then return e[2] end
		end
	end
	return "star"
end

