-- Rend un cadre déplaçable ; la position est retenue dans Prefs[key].
local function Draggable(frame, handle, key)
	local dragging, start, origin = false, nil, nil
	Library:Connect(handle.InputBegan, function(input)
		if not IsClick(input) then return end
		dragging = true
		start = K.InputPos(input)
		local tl = frame.AbsolutePosition - ScreenGui.AbsolutePosition
		local f = Factor()
		local ap = frame.AnchorPoint
		origin = tl + frame.AbsoluteSize * ap
		local _ = f
	end)
	Library:Connect(UserInputService.InputChanged, function(input)
		if dragging and IsMove(input) then
			local p = origin + (K.InputPos(input) - start)
			frame.Position = UDim2.fromOffset(p.X, p.Y)
		end
	end)
	Library:Connect(UserInputService.InputEnded, function(input)
		if dragging and IsClick(input) then
			dragging = false
			if key then
				local vp = ViewportSize()
				local p = frame.Position
				Prefs[key] = { p.X.Offset / vp.X, p.Y.Offset / vp.Y }
				K.SavePrefs()
			end
		end
	end)
	if key and type(Prefs[key]) == "table" then
		task.defer(function()
			local vp = ViewportSize()
			frame.Position = UDim2.fromOffset(Prefs[key][1] * vp.X, Prefs[key][2] * vp.Y)
		end)
	end
end
K.Draggable = Draggable

local function MiniPanel(name, width, z)
