task.spawn(function()
    while Hub.Alive do
        if questStatusLabel and questProgressLabel and questsCompletedLabel then
            pcall(function()
                questStatusLabel:SetText(string.format("Status: %s", tostring(Hub.QuestState.Phase or "Idle")))
                questProgressLabel:SetText(string.format("Objective: %d / %d (%s)", Hub.QuestState.Kills or 0, Hub.QuestState.TargetKills or 0, tostring(Hub.QuestState.CurrentQuest or "None")))
                questsCompletedLabel:SetText(string.format("Completed Quests: %d", Hub.RunStats.QuestsCompleted or 0))
            end)
        end
        task.wait(0.5)
    end
end)

